/* eslint-disable @typescript-eslint/no-unused-vars */
/* eslint-disable import/no-internal-modules */
import 'pepjs'
import { Host } from '@flowpub/glue-rpc'
import { EventHandlingService } from '@flowpub/glue-modules'

import { LinkHandlingService } from './link-handling'
import { SelectionChangeHandlingService } from './selection-handling'
import { HighlightHandlingService } from './highlight-handling'
import { PanHandlingService } from './pan-handling'
import { TabFocusHandlingService } from './tab-focus-handling'
import { WheelHandlingService } from './wheel-handling'
import { PageLabelHandlingService } from './page-label-handling'
import { AssistiveSelectionHandlingService } from './assistive-selection/assistive-selection-handling'

// eslint-disable-next-line no-unused-vars
const eventHandling = new Host('event-handling', EventHandlingService)
// eslint-disable-next-line no-unused-vars
const linkHandling = new Host('link-handling', LinkHandlingService)
// eslint-disable-next-line no-unused-vars
const selectionChangeHandling = new Host(
  'selection-handling',
  SelectionChangeHandlingService,
)
// eslint-disable-next-line no-unused-vars
const highlightHandling = new Host(
  'highlight-handling',
  HighlightHandlingService,
)

// eslint-disable-next-line no-unused-vars
const pageLabelHandling = new Host(
  'page-label-handling',
  PageLabelHandlingService,
)

// eslint-disable-next-line no-unused-vars
const assistiveSelectionHandling = new Host(
  'assistive-selection-handling',
  AssistiveSelectionHandlingService,
)

// eslint-disable-next-line no-unused-vars
const panHandling = new Host('pan-handling', PanHandlingService)
// eslint-disable-next-line no-unused-vars
const tabFocusHanlding = new Host('tab-focus-handling', TabFocusHandlingService)

// eslint-disable-next-line no-unused-vars
const wheelHandling = new Host('wheel-handling', WheelHandlingService)

const selectionService: SelectionChangeHandlingService = selectionChangeHandling.getService()
selectionService.setHighlightService(highlightHandling.getService())
selectionService.setAssistiveSelectionService(
  assistiveSelectionHandling.getService(),
)
