import * as EPUBcfi from '@evidentpoint/readium-cfi-js'
import {
  EventListenerService,
  CallSource,
  Callback,
  TouchTracker,
} from '@flowpub/glue-shared'
import {
  degausser,
  getRangeFromOffset as getDegaussedRangeFromOffset,
} from 'degausser'

import {
  elementBlacklist,
  idBlacklist,
  classBlacklist,
} from './default-blacklist'
import { Comparison, Rect } from './types'
import {
  checkIfTwoRectanglesOverlap,
  getRectsFromDomRects,
  calculateRectsMinMax,
  collectNodesWithinRange,
  getOffsetFromRange,
  getTextNodesRectsInRange,
  getSelfNodeOrFirstParentOfTypeOrNull,
} from './utils'

export const HighlightAddMessage = 'HIGHLIGHT_ADD'
export const HighlightRedrawMessage = 'HIGHLIGHT_REDRAW'
export const HighlightDeletionMessage = 'HIGHLIGHT_DELETION'
export const HighlightUpdateMessage = 'HIGHLIGHT_UPDATE'
export const HighlightVisibleRangeUpdateMessage =
  'HIGHLIGHT_VISIBLE_RANGE_UPDATE'
export const AddHighlightSelectedListenerMessage =
  'ADD_HIGHLIGHT_SELECTED_LISTENER'
export const RemoveHighlightSelectedListenerMessage =
  'REMOVE_HIGHLIGHT_SELECTED_LISTENER'
export const SetEphemeralHighlightDeletedCallbackMessage =
  'SET_EPHEMERAL_HIGHLIGHT_DELETE_CALLBACK'

const HighlightIDAttribute = 'highlight-id'

// The maximum value of error in pixels.
// Even if the error is presented, two objects are regarded as being intersected
const IntersectionErrorThresholdPx = 3

interface DegausserMapEntry {
  start: number
  length: number
  node: Node
  content: string
}

export enum HighlightType {
  CFI,
  Offset,
}

interface RectGroup {
  rects: Rect[]
  isImage: boolean
}

export interface Highlight {
  elements: HTMLElement[]
  rectGroups: RectGroup[]
  rectMinMax: [number, number]
  id: string
  type: HighlightType
  start: string | number
  end: string | number
  color: string
  duration: number
}

export interface SingleHighlightInfo {
  id: string
  rects: Rect[]
}

export interface SelectedHighlightInfo {
  touchPoint: Rect
  highlights: SingleHighlightInfo[]
}

export class HighlightHandlingService extends EventListenerService {
  private readonly fadeInDuration = 300
  private readonly fadeOutDuration = 225
  private ephemeralHighlightDeletedCallback: Callback
  private highlightIdMap: Map<string, Highlight> = new Map<string, Highlight>() // id to highlight map
  private rectIdMap: Map<string, Rect[]> = new Map<string, Rect[]>() // id to rects

  private listenerId: number

  private _degaussedMap: DegausserMapEntry[]
  private highlightPointerUpListenerOrUndefined: (
    ev: PointerEvent,
  ) => void | undefined
  get degaussedMap(): DegausserMapEntry[] {
    // Have to do this as a lazy load
    //  Otherwise it fails when run during the constructor
    if (!this._degaussedMap) {
      this._degaussedMap = degausser(document, {
        map: true,
        elementBlacklist,
        idBlacklist,
        classBlacklist,
      })
    }
    return this._degaussedMap
  }

  private visibleRange = [0, 0]

  constructor(source: CallSource) {
    super(source)

    source.bind(HighlightDeletionMessage, this.deleteHighlight)
    source.bind(HighlightAddMessage, this.addHighlight)
    source.bind(HighlightRedrawMessage, this.redrawHighlights)
    source.bind(HighlightUpdateMessage, this.updateHighlight)

    source.bind(HighlightVisibleRangeUpdateMessage, this.visibleRangeUpdate)

    source.bind(
      AddHighlightSelectedListenerMessage,
      this.addHighlightSelectedListener,
    )

    source.bind(
      RemoveHighlightSelectedListenerMessage,
      this.removeEventListener,
    )

    source.bind(
      SetEphemeralHighlightDeletedCallbackMessage,
      this.setEphemeralHighlightDeletedCallback,
    )

    this.setPreventDefaultHandlingIfTapOnHighlight()
    this.setPreventOpeningLinksHighlighted()
  }

  /**
   * Returns the ids of highlights that overlap with the given range object.
   * This checks overlap by text, not by overlapping rects.
   *
   * @param selectedRange range to check for overlapping highlights
   */
  public getOverlappingHighlightIds(
    selectedRange: Range | undefined,
  ): string[] {
    if (selectedRange === undefined) {
      return []
    }

    const entries = this.highlightIdMap.entries()
    let entry
    const selectedHighlightIds: string[] = []

    while ((entry = entries.next().value)) {
      const highlightId = entry[0]
      const highlight: Highlight = entry[1]

      let startComparison: [Comparison, Comparison]
      let endComparison: [Comparison, Comparison]
      if (highlight.type === HighlightType.CFI) {
        const selectionCfi = EPUBcfi.Generator.generateRangeComponent(
          selectedRange.startContainer,
          selectedRange.startOffset,
          selectedRange.endContainer,
          selectedRange.endOffset,
          classBlacklist,
          elementBlacklist,
          idBlacklist,
        )
        startComparison = EPUBcfi.Interpreter.compareCFIs(
          `epubcfi(/99!${selectionCfi})`,
          `epubcfi(/99!${highlight.start})`,
        )
        endComparison = EPUBcfi.Interpreter.compareCFIs(
          `epubcfi(/99!${selectionCfi})`,
          `epubcfi(/99!${highlight.end})`,
        )
      } else {
        // highlight.type === HighlightType.Offset
        const selectionStartOffset = getOffsetFromRange(selectedRange, true)
        const selectionEndOffset = getOffsetFromRange(selectedRange, false)
        startComparison = [
          Math.sign(selectionStartOffset - (highlight.start as number)),
          Math.sign(selectionEndOffset - (highlight.start as number)),
        ]
        endComparison = [
          Math.sign(selectionStartOffset - (highlight.end as number)),
          Math.sign(selectionEndOffset - (highlight.end as number)),
        ]
      }

      const highlightStartsAfterSelectionEnd =
        startComparison[1] === Comparison.Forward ||
        startComparison[1] === Comparison.Identical
      const selectionStartsAfterHighlightEnd =
        endComparison[0] === Comparison.Backward ||
        endComparison[0] === Comparison.Identical
      if (
        !(highlightStartsAfterSelectionEnd || selectionStartsAfterHighlightEnd)
      ) {
        // selection intersects highlight
        selectedHighlightIds.push(highlightId)
      }
    }

    return selectedHighlightIds
  }

  public getSelectedHighlights(
    selectionTopLeftCornerXCoordinate: number,
    selectionTopLeftCornerYCoordinate: number,
    bottomRightSelectionCoordinate?: { x: number; y: number },
  ): SelectedHighlightInfo {
    const entries = this.rectIdMap.entries()
    // TODO - if there is a reason to run this code outside of an iframe element
    // (eg in a top level window), this code will fail by throwing an exception.
    let entry
    const frameRect = window.frameElement!.getBoundingClientRect()
    const selectedHighlightInfo: SelectedHighlightInfo = {
      touchPoint: {
        x: selectionTopLeftCornerXCoordinate + frameRect.x,
        y: selectionTopLeftCornerYCoordinate + frameRect.y,
        width: 0,
        height: 0,
      },
      highlights: [],
    }
    const selectionRect: Rect = {
      x: selectionTopLeftCornerXCoordinate,
      y: selectionTopLeftCornerYCoordinate,
      width: bottomRightSelectionCoordinate
        ? bottomRightSelectionCoordinate.x - selectionTopLeftCornerXCoordinate
        : 0,
      height: bottomRightSelectionCoordinate
        ? bottomRightSelectionCoordinate.y - selectionTopLeftCornerYCoordinate
        : 0,
    }

    while ((entry = entries.next().value)) {
      const rects = entry[1]

      for (const rect of rects) {
        const isOverlappingWithSelectionRect = checkIfTwoRectanglesOverlap(
          rect,
          selectionRect,
          IntersectionErrorThresholdPx,
        )

        if (!isOverlappingWithSelectionRect) {
          continue
        }

        const highlightId = entry[0]
        let highlight
        if (highlightId) {
          highlight = this.highlightIdMap.get(highlightId)
        }

        const highlightRects: Rect[] = []
        if (highlight) {
          for (const el of highlight.elements) {
            const highlightRect = el.getBoundingClientRect()
            // rect positions in callback need to be relative to webview, not iframe
            highlightRects.push({
              x: frameRect.x + highlightRect.x,
              y: frameRect.y + highlightRect.y,
              width: highlightRect.width,
              height: highlightRect.height,
            })
          }
        }

        const singleHighlightInfo: SingleHighlightInfo = {
          id: entry[0],
          rects: highlightRects,
        }
        selectedHighlightInfo.highlights.push(singleHighlightInfo)
        break
      }
    }

    return selectedHighlightInfo
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private getTextTerminusInfo(partialCFI: string): any {
    if (EPUBcfi.Interpreter.hasTextTerminus(`epubcfi(/99!${partialCFI})`)) {
      let textTerminusResult
      try {
        textTerminusResult = EPUBcfi.Interpreter.getTextTerminusInfo(
          `epubcfi(/99!${partialCFI})`,
          document,
          classBlacklist,
          idBlacklist,
          elementBlacklist,
        )
        return textTerminusResult
      } catch (ex) {
        // EPUBcfi.Interpreter can throw a SyntaxError
      }
    } else {
      let cfiTargetElement
      try {
        cfiTargetElement = EPUBcfi.Interpreter.getTargetElement(
          `epubcfi(/99!${partialCFI})`,
          document,
          classBlacklist,
          idBlacklist,
          elementBlacklist,
        )
        if (!cfiTargetElement || cfiTargetElement.length === 0) {
          return null
        }

        return {
          textNode: cfiTargetElement[0],
          textOffset: 0,
        }
      } catch (ex) {
        // EPUBcfi.Interpreter can throw a SyntaxError
      }
    }

    return null
  }

  private getRangeFromCfi(startCFI: string, endCFI: string): Range | null {
    const startPosition = this.getTextTerminusInfo(startCFI)
    const endPosition = this.getTextTerminusInfo(endCFI)
    if (startPosition === null || endPosition === null) {
      return null
    }

    const range = document.createRange()

    range.setStart(startPosition.textNode, startPosition.textOffset)
    range.setEnd(endPosition.textNode, endPosition.textOffset)
    return range
  }

  private calculateRangeRects(
    range: Range,
  ): [RectGroup[], Rect[], [number, number]] {
    const nodes = collectNodesWithinRange(range)

    const workingRange = document.createRange()
    workingRange.setStart(range.startContainer, range.startOffset)

    let allRects: Rect[] = []
    const rectGroups: RectGroup[] = []
    for (const node of nodes) {
      if (
        node.nodeType === Node.ELEMENT_NODE &&
        (node as HTMLElement).tagName === 'img'
      ) {
        workingRange.setEndBefore(node)

        const textRects = getRectsFromDomRects(workingRange.getClientRects())
        allRects = allRects.concat(textRects)
        rectGroups.push({ rects: textRects, isImage: false })

        workingRange.selectNode(node)
        const imgRects = getRectsFromDomRects(workingRange.getClientRects())
        allRects = allRects.concat(imgRects)
        rectGroups.push({ rects: imgRects, isImage: true })

        workingRange.collapse(false)
        workingRange.setStartAfter(node)
      }
    }

    workingRange.setEnd(range.endContainer, range.endOffset)

    // workingRange.getClientRects() - the native API returns all elements selected
    // (e.g. <p> - paragraphs) that might be wider than the actual text selected, also
    // these rectangles might intersect with each other which causes a necessity of filtering
    // them or shrinking their size to avoid overlapping of highlighted elements, which causes
    // changing of their colors.
    // This filtration can cause loss of some rectangles which leads to not all selected text being
    // coloured as highlighted. In Firefox this causes anchors are not highlighted at all.
    // Instead of having complex logic(like getRectsFromDomRects(workingRange.getClientRects()) has)
    // it's better to pick DOMRects of the text selected actually, and color them only.
    const rects = getTextNodesRectsInRange(workingRange)

    allRects = allRects.concat(rects)
    rectGroups.push({ rects: rects, isImage: false })

    const rectRange = calculateRectsMinMax(allRects)

    return [rectGroups, allRects, rectRange]
  }

  private drawRectList(
    rects: Rect[],
    colour: string,
    isImage: boolean,
    id: string,
    fadeIn = false,
  ): HTMLElement[] {
    const divs = []

    for (let i = 0; i < rects.length; ++i) {
      const highlight = document.createElement('div')
      highlight.classList.add('highlight-rect')
      highlight.setAttribute(HighlightIDAttribute, id)

      const style = highlight.style

      style.top = `${rects[i].y}px`
      style.left = `${rects[i].x}px`
      style.width = `${rects[i].width}px`
      style.height = `${rects[i].height}px`

      style.backgroundColor = colour

      style.position = 'absolute'
      style.zIndex = '0'

      style.pointerEvents = 'none'

      const targetOpacity = isImage ? '0.2' : '0.4'

      if (fadeIn) {
        style.opacity = '0'
        style.transitionDuration = `${this.fadeInDuration}ms`
        style.transitionProperty = 'opacity'
        window.requestAnimationFrame(() => {
          // this is required for transition to work properly
          style.opacity = targetOpacity
        })
      } else {
        style.opacity = targetOpacity
      }

      document.documentElement.appendChild(highlight)

      divs.push(highlight)
    }

    return divs
  }

  private async deleteHighlight(_: Callback, id: string): Promise<void> {
    const highlight = this.highlightIdMap.get(id)
    if (!highlight) {
      return
    }

    for (const el of highlight.elements) {
      el.remove()
    }

    this.highlightIdMap.delete(id)
    this.rectIdMap.delete(id)
  }

  private async updateHighlight(
    _: Callback,
    id: string,
    color: string,
  ): Promise<void> {
    const highlight = this.highlightIdMap.get(id)
    if (!highlight) {
      return
    }

    highlight.color = color
    for (const el of highlight.elements) {
      el.style.backgroundColor = color
    }
  }

  private async setEphemeralHighlightDeletedCallback(
    callback: Callback,
  ): Promise<void> {
    this.ephemeralHighlightDeletedCallback = callback
  }

  private async addHighlightSelectedListener(
    callback: Callback,
  ): Promise<number> {
    const touchTracker = new TouchTracker()
    const downEvent = (event: Event): void => {
      touchTracker.onPointerDown(event as MouseEvent)
    }

    const upEvent = (event: Event): void => {
      touchTracker.onPointerUp(event as MouseEvent)

      if (!touchTracker.isDone()) return

      const isPressedLong = touchTracker.pressedLong()
      const isDragging = touchTracker.isDragging()
      const isMovingTap = touchTracker.movedLong()
      if (isPressedLong || isDragging || isMovingTap) {
        return
      }

      const pEvent = event as PointerEvent

      const selectedHighlightInfo = this.getSelectedHighlights(
        pEvent.clientX,
        pEvent.clientY,
      )
      if (selectedHighlightInfo.highlights.length > 0) {
        pEvent.stopPropagation()
        callback(selectedHighlightInfo)
      }
    }

    this.registerListenerForTargets('@document', 'pointerdown', downEvent)

    this.highlightPointerUpListenerOrUndefined = upEvent
    this.listenerId = this.registerListenerForTargets(
      '@document',
      'pointerup',
      upEvent,
    )

    return this.listenerId
  }

  private async removeEventListener(
    _callback: Callback,
    listenerID: number,
  ): Promise<void> {
    this.removeEventListeners(listenerID)
  }

  private async addHighlight(
    _: Callback,
    id: string,
    type: HighlightType,
    start: string | number,
    end: string | number,
    color: string,
    duration: number,
  ): Promise<void> {
    const elements: HTMLElement[] = []
    const rectGroups: RectGroup[] = []
    const newHighlight = {
      elements,
      rectGroups,
      rectMinMax: [0, 0],
      id,
      type,
      start,
      end,
      color,
      duration,
    }

    this.addOrRedrawHighlightInternal(newHighlight as Highlight)
  }

  private addOrRedrawHighlightInternal(highlight: Highlight): void {
    let highlightRange: Range | null = null
    const start = highlight.start
    const end = highlight.end
    switch (highlight.type) {
      case HighlightType.CFI:
        highlightRange = this.getRangeFromCfi(start as string, end as string)
        break
      case HighlightType.Offset:
        highlightRange = getDegaussedRangeFromOffset(
          start as number,
          end as number,
          document,
          this.degaussedMap,
        )
        break
    }

    if (highlightRange === null) {
      this.removeHighlightRendering(highlight)
      return
    }
    this.addHighlightByRange(highlight, highlightRange)
  }

  private addHighlightByRange(
    highlight: Highlight,
    highlightRange: Range,
  ): void {
    const [rectGroups, rects, rectMinMax] = this.calculateRangeRects(
      highlightRange,
    )

    if (this.checkIfRectsChanged(highlight, rectGroups)) {
      this.removeHighlightRendering(highlight)

      highlight.rectGroups = rectGroups
      highlight.rectMinMax = rectMinMax

      this.realizeHighlightIfVisible(highlight)

      this.highlightIdMap.set(highlight.id, highlight as Highlight)

      this.rectIdMap.set(highlight.id, rects)
    }
  }

  private async redrawHighlights(_: Callback): Promise<void> {
    this.highlightIdMap.forEach((highlight: Highlight, _id: string) => {
      this.addOrRedrawHighlightInternal(highlight)
    })
  }

  private async visibleRangeUpdate(
    _: Callback,
    startOffset: number,
    endOffset: number,
  ): Promise<void> {
    this.visibleRange[0] = startOffset
    this.visibleRange[1] = endOffset

    this.highlightIdMap.forEach((val) => {
      this.realizeHighlightIfVisible(val)
    })
  }

  private realizeHighlightIfVisible(highlight: Highlight): void {
    if (highlight.elements.length > 0) {
      return
    }

    if (
      highlight.rectMinMax[1] < this.visibleRange[0] ||
      highlight.rectMinMax[0] > this.visibleRange[1]
    ) {
      return
    }

    for (const rectGroup of highlight.rectGroups) {
      const elements = this.drawRectList(
        rectGroup.rects,
        highlight.color,
        rectGroup.isImage,
        highlight.id,
        !!highlight.duration,
      )

      highlight.elements = highlight.elements.concat(elements)
    }

    if (highlight.duration) {
      setTimeout(() => {
        this.removeHighlightRendering(highlight, true)
      }, highlight.duration + this.fadeInDuration)
    }
  }

  private removeHighlightRendering(
    highlight: Highlight,
    fadeOut = false,
  ): void {
    if (fadeOut) {
      for (const el of highlight.elements) {
        el.style.transitionDuration = `${this.fadeOutDuration}ms`
        el.style.opacity = '0'
      }

      setTimeout(() => {
        this.removeHighlightRendering(highlight, false)
        this.ephemeralHighlightDeletedCallback?.(highlight.id)
      }, this.fadeOutDuration)

      return
    }

    if (highlight.elements.length > 0) {
      for (const el of highlight.elements) {
        el.remove()
      }
    }
    highlight.elements = []
    highlight.rectGroups = []
  }

  private checkIfRectsChanged(
    highlight: Highlight,
    rectGroups: RectGroup[],
  ): boolean {
    if (highlight.rectGroups.length !== rectGroups.length) {
      return true
    }

    for (let i = 0; i < rectGroups.length; i += 1) {
      const oldGroup = highlight.rectGroups[i]
      const newGroup = rectGroups[i]
      if (
        oldGroup.isImage !== newGroup.isImage ||
        oldGroup.rects.length !== newGroup.rects.length
      ) {
        return true
      }

      for (let j = 0; j < newGroup.rects.length; j += 1) {
        const oldRect = oldGroup.rects[j]
        const newRect = newGroup.rects[j]
        if (
          !this.diffWithInRange(oldRect.x, newRect.x) ||
          !this.diffWithInRange(oldRect.y, newRect.y) ||
          !this.diffWithInRange(oldRect.width, newRect.width) ||
          !this.diffWithInRange(oldRect.height, newRect.height)
        ) {
          return true
        }
      }
    }

    return false
  }

  private diffWithInRange(val1: number, val2: number): boolean {
    return Math.abs(val1 - val2) < 0.5
  }

  private setPreventOpeningLinksHighlighted(): void {
    const touchOnHighlightingTracker = new TouchTracker()

    document.addEventListener(
      'pointerdown',
      (ev: PointerEvent) => {
        touchOnHighlightingTracker.onPointerDown(ev)
      },
      {
        capture: true,
        passive: true,
      },
    )

    document.addEventListener(
      'pointermove',
      (ev: PointerEvent) => {
        touchOnHighlightingTracker.onPointerMove(ev)
      },
      {
        capture: true,
        passive: true,
      },
    )

    document.addEventListener(
      'pointerup',
      (ev: PointerEvent) => {
        touchOnHighlightingTracker.onPointerUp(ev)

        const evTarget = ev.target
        if (!evTarget) {
          return
        }

        const isDragging = touchOnHighlightingTracker.isDragging()
        const isLongPress = touchOnHighlightingTracker.pressedLong()
        const isMoving = touchOnHighlightingTracker.movedLong()

        if (isDragging || isLongPress || isMoving) {
          return
        }

        // clientX, clientY should be used, since highlight rects are using the same
        // coordinate system - current viewport instead of the entire page
        // https://developer.mozilla.org/en-US/docs/Web/API/Touch/clientX
        const { clientX, clientY } = ev
        const selectedHighlightInfo = this.getSelectedHighlights(
          clientX,
          clientY,
        )

        if (
          selectedHighlightInfo.highlights.length > 0 &&
          getSelfNodeOrFirstParentOfTypeOrNull(evTarget as Node, 'a')
        ) {
          // stop the propagation at the top level only for anchor nodes
          ev.preventDefault()
          ev.stopPropagation()
          ev.stopImmediatePropagation()
          this.highlightPointerUpListenerOrUndefined?.(ev)
        }
      },
      {
        capture: true,
        passive: false,
      },
    )

    document.addEventListener(
      'click',
      (ev: MouseEvent) => {
        const evTarget = ev.target

        if (!evTarget) {
          return
        }

        const { clientX, clientY } = ev
        const selectedHighlightInfo = this.getSelectedHighlights(
          clientX,
          clientY,
        )

        if (
          selectedHighlightInfo.highlights.length > 0 &&
          getSelfNodeOrFirstParentOfTypeOrNull(evTarget as Node, 'a')
        ) {
          // stop the propagation at the top level only for anchor nodes
          ev.preventDefault()
          ev.stopPropagation()
          ev.stopImmediatePropagation()
        }
      },
      {
        capture: true,
        passive: false,
      },
    )
  }

  private setPreventDefaultHandlingIfTapOnHighlight(): void {
    // this is initially written to prevent Google Chrome's "tap to search"
    // feature https://developers.google.com/web/updates/2015/10/tap-to-search
    const touchOnHighlightingTracker = new TouchTracker()
    document.addEventListener(
      'touchstart',
      (ev: TouchEvent) => {
        touchOnHighlightingTracker.onPointerDown(ev)
      },
      {
        capture: true,
        passive: true,
      },
    )

    document.addEventListener(
      'touchmove',
      (ev: TouchEvent) => {
        touchOnHighlightingTracker.onPointerMove(ev)
      },
      {
        capture: true,
        passive: true,
      },
    )

    document.addEventListener(
      'touchend',
      (ev: TouchEvent) => {
        touchOnHighlightingTracker.onPointerUp(ev)
        if (ev.changedTouches?.length > 1) {
          return
        }
        const isDragging = touchOnHighlightingTracker.isDragging()
        const isLongPress = touchOnHighlightingTracker.pressedLong()
        const isMoving = touchOnHighlightingTracker.movedLong()

        if (isDragging || isLongPress || isMoving) {
          return
        }

        const touch = (ev as TouchEvent).changedTouches?.[0]

        if (!touch) {
          return
        }

        const { clientX, clientY } = touch
        const selectedHighlightInfo = this.getSelectedHighlights(
          clientX,
          clientY,
        )

        if (selectedHighlightInfo.highlights.length > 0) {
          ev.preventDefault()
        }
      },
      {
        capture: true,
        passive: false,
      },
    )
  }
}
