import {
  Callback,
  CallSource,
  EventListenerService,
  PanEventHandler,
} from '@flowpub/glue-shared'

export const PanHandlingMessageAddListener = 'ADD_PAN_LISTENER'
export const PanHandlingMessageRemoveListener = 'REMOVE_PAN_LISTENER'

export class PanHandlingService extends EventListenerService {
  private panEventHandler: PanEventHandler

  constructor(source: CallSource) {
    super(source)

    source.bind(PanHandlingMessageAddListener, this.addPanListener)
    source.bind(PanHandlingMessageRemoveListener, this.removePanListener)
  }

  private async addPanListener(callback: Callback): Promise<number> {
    this.panEventHandler = new PanEventHandler(callback)

    this.registerListenerForTargets(
      '@document',
      'touchstart',
      this.panEventHandler.prePanCheckEvent,
    )
    this.registerListenerForTargets(
      '@document',
      'touchmove',
      this.panEventHandler.moveEvent,
    )
    this.registerListenerForTargets(
      '@document',
      'touchend',
      this.panEventHandler.endEvent,
    )

    const selectionEvent = (_: Event): void => {
      const currentSelection = document.getSelection()?.toString()
      if (currentSelection && currentSelection.length > 0) {
        this.panEventHandler.setSelectionIsPresent(true)
        return
      }
      this.panEventHandler.setSelectionIsPresent(false)
    }

    return this.registerListenerForTargets(
      '@document',
      'selectionchange',
      selectionEvent,
    )
  }

  private async removePanListener(
    _callback: Callback,
    listenerID: number,
  ): Promise<void> {
    this.removeEventListeners(listenerID)
  }
}
