import { degausser } from 'degausser'

import { Rect } from './types'
import {
  classBlacklist,
  elementBlacklist,
  idBlacklist,
} from './default-blacklist'
import { SingleHighlightInfo } from './highlight-handling'

/**
 * Converts Range rects to Rect interface and filters
 * out some rects along the way (rects which completely encompass other rects
 * are filtered, rects which encompass along the Y axis but overlap
 * along the X axis are filtered)
 *
 * TODO: For elements completely in range, Firefox returns only
 * the full-width bounding rect. If text inside such element is shifted outside
 * the boundaries (like with negative text-indent), the resulted rect position
 * will not account for that and will visually not cover all the text selected.
 *
 * @param domRects
 */
export function getRectsFromDomRects(domRects: DOMRectList): Rect[] {
  const rects: Rect[] = []

  for (let i = 0; i < domRects.length; ++i) {
    const domRect = domRects[i]
    const domRectBottom = domRect.top + domRect.height
    const domRectRight = domRect.left + domRect.width
    let skipRect = false

    for (let j = 0; j < domRects.length; ++j) {
      if (j === i) {
        continue
      }
      const otherRect = domRects[j]
      const otherRectBottom = otherRect.top + otherRect.height
      const otherRectRight = otherRect.left + otherRect.width
      const isEncompassingOtherRect =
        domRect.left <= otherRect.left &&
        domRect.top <= otherRect.top &&
        otherRect.width !== 0 &&
        otherRect.height !== 0 &&
        domRectRight >= otherRectRight &&
        domRectBottom >= otherRectBottom

      if (isEncompassingOtherRect) {
        if (
          domRect.left === otherRect.left &&
          domRect.top === otherRect.top &&
          domRectRight === otherRectRight &&
          domRectBottom === otherRectBottom &&
          i < j // only get the first rect of equal size/position
        ) {
          continue
        }
        // skip rect if it encompasses any other rect
        // e.g., paragraph rect encompasses line rects
        skipRect = true
        break
      } else if (
        domRect.top <= otherRect.top &&
        domRectBottom >= otherRectBottom &&
        domRect.left < otherRectRight &&
        domRect.right > otherRect.left
      ) {
        // skip rect if it encompasses any other rect vertically,
        // but only partially overlaps horizontally.
        // this happens when text is shifted outside it's container
        // (like paragraph), for instance with negative "text-indent"
        skipRect = true
        break
      }
    }
    if (skipRect) {
      continue
    }
    const rect = {
      x: domRect.left,
      y: domRect.top,
      width: domRect.width,
      height: domRect.height,
    }
    rects.push(rect as Rect)
  }

  return rects
}

export function calculateRectsMinMax(rects: Rect[]): [number, number] {
  let minX = Number.MAX_SAFE_INTEGER
  let maxX = 0
  for (const r of rects) {
    if (minX > r.x) {
      minX = r.x
    }
    if (maxX < r.x + r.width) {
      maxX = r.x + r.width
    }
  }

  return [minX, maxX]
}

export function getHrefFromElement(ele: HTMLElement): string | null {
  let href = null
  const xlinkHrefAttr = ele.attributes.getNamedItem('xlink:href')
  if (xlinkHrefAttr) {
    href = xlinkHrefAttr.value
  }

  if (!href) {
    const hrefAttr = ele.attributes.getNamedItem('href')
    if (hrefAttr) {
      href = hrefAttr.value
    }
  }

  return href
}

export function collectNodesWithinRange(range: Range): Node[] {
  const iterator = document.createNodeIterator(
    range.commonAncestorContainer,
    NodeFilter.SHOW_ALL,
    {
      acceptNode() {
        return NodeFilter.FILTER_ACCEPT
      },
    },
  )

  const nodes = []
  while (iterator.nextNode()) {
    // Skip all nodes until the start container
    if (nodes.length === 0 && iterator.referenceNode !== range.startContainer) {
      continue
    }

    nodes.push(iterator.referenceNode)

    // Break on the last container in range
    if (iterator.referenceNode === range.endContainer) {
      break
    }
  }
  return nodes
}

export function getNodeRects(
  node: Node,
  startOffset: number,
  endOffset: number,
): DOMRect[] {
  const range = document.createRange()
  range.setStart(node, startOffset)
  range.setEnd(node, endOffset)
  // getBoundingClientRect returns only one rectangle encapsulating all the text,
  // but multiline text might consists of several rectangles
  return Array.from(range.getClientRects())
}

export function getWholeNodeRects(node: Node): DOMRect[] {
  const range = document.createRange()
  range.selectNode(node)
  // getBoundingClientRect returns only one rectangle encapsulating all the text,
  // but multiline text might consists of several rectangles
  return Array.from(range.getClientRects())
}

export function isTextNode(node: Node): boolean {
  return node.nodeType === 3
}

export function getRangeForNode(
  node: Node,
  startOffset: number,
  endOffset: number,
): Range {
  const rangeForNode = document.createRange()
  rangeForNode.setStart(node, startOffset)
  rangeForNode.setEnd(node, endOffset)
  return rangeForNode
}

/**
 * Adapted and fixed from https://gist.github.com/chriszarate/5092641,
 * http://stackoverflow.com/questions/4398526/how-can-i-find-all-text-nodes-between-to-element-nodes-with-javascript-jquery
 * Returns DOMRects for all text nodes within
 * the range.
 *
 * @export
 * @param {Range} range
 * @returns {DOMRect[]}
 */
export function getTextNodesRectsInRange(range: Range): DOMRect[] {
  const rootNode = range.commonAncestorContainer

  const startNode = range.startContainer
  const startOffset = range.startOffset

  const endNode = range.endContainer
  const endOffset = range.endOffset

  const textNodesRects: DOMRect[] = []
  let pastStartNode = false
  let reachedEndNode = false

  if (startNode === endNode && rootNode === startNode) {
    return getNodeRects(startNode, startOffset, endOffset)
  }

  // TODO - refactor this to traverse the tree using a stack
  function getTextNodesRects(node?: Node): void {
    if (!node) {
      return
    }

    const nodeTextValueOrNull = node.nodeValue
    // "|| isTextNode(node)" - this condition is necessary for the case
    // if there is only a text node is selected
    const isStartNode = node === startNode
    const isEndNode = node === endNode

    if (isStartNode && isEndNode && (node !== rootNode || isTextNode(node))) {
      if (
        isTextNode(node) &&
        startOffset === 0 &&
        endOffset === nodeTextValueOrNull?.length
      ) {
        // if the entire text node is selected
        textNodesRects.push(...getWholeNodeRects(node))
      } else if (nodeTextValueOrNull) {
        textNodesRects.push(
          ...getNodeRects(node, startOffset, endOffset),
          // the original code - val.substring(startOffset, endOffset)
        )
      }
      pastStartNode = reachedEndNode = true
    } else if (isStartNode) {
      if (nodeTextValueOrNull) {
        textNodesRects.push(
          ...getNodeRects(node, startOffset, nodeTextValueOrNull.length),
          // the original code - val.substring(startOffset)
        )
      }
      pastStartNode = true
    } else if (isEndNode) {
      if (nodeTextValueOrNull) {
        textNodesRects.push(
          ...getNodeRects(node, 0, endOffset),
          // the original code - val.substring(0, endOffset)
        )
      }
      reachedEndNode = isTextNode(node) || !endOffset
    } else if (isTextNode(node)) {
      if (
        nodeTextValueOrNull &&
        pastStartNode &&
        !reachedEndNode &&
        !/^\s*$/.test(nodeTextValueOrNull)
      ) {
        textNodesRects.push(
          ...getWholeNodeRects(node),
          // the original code - val
        )
      }
    }

    let i = isStartNode ? startOffset : 0
    const len = isEndNode ? endOffset : node.childNodes.length

    for (; !(reachedEndNode && !endOffset) && i < len; ++i) {
      getTextNodesRects(node.childNodes[i])
    }
    if (isEndNode) {
      reachedEndNode = true
    }
  }

  getTextNodesRects(rootNode)
  return textNodesRects
}

export function getSelfNodeOrFirstParentOfTypeOrNull(
  node: Node,
  nodeName: Node['nodeName'],
): Node | null {
  const requiredParentNodeNameUpperCase = nodeName.trim().toLowerCase()
  let currentNodeOrNull: Node | null = node
  while (currentNodeOrNull) {
    if (
      currentNodeOrNull.nodeName.toLowerCase() ===
      requiredParentNodeNameUpperCase
    ) {
      return currentNodeOrNull
    }
    currentNodeOrNull = currentNodeOrNull.parentNode
  }
  return null
}

/**
 * Returns the text offset of a range, at start or end.
 *
 * @param range
 * @param atStart true if getting offset at start of range, otherwise end of range
 */
export function getOffsetFromRange(range: Range, atStart: boolean): number {
  const rangeCopy = range.cloneRange()
  rangeCopy.collapse(atStart)
  rangeCopy.setStartBefore(document.documentElement)
  return degausser(rangeCopy.cloneContents(), {
    elementBlacklist,
    idBlacklist,
    classBlacklist,
  }).length
}

/**
 * Merge the list of non-unique highlights into a list with
 * unique highlight only.
 *
 * @export
 * @param {...Array<SingleHighlightInfo[]>} listsWithHighlights - a list of highlights.
 * @return {SingleHighlightInfo[]} - a list of unique only highlights. Each unique highligh will be presented only once.
 */
export function mergeHighlightListsToUniqHighlights(
  ...listsWithHighlights: Array<SingleHighlightInfo[]>
): SingleHighlightInfo[] {
  const highlights: SingleHighlightInfo[][] | SingleHighlightInfo[] = [
    ...listsWithHighlights,
  ]
  const highlightItems: SingleHighlightInfo[] = []
  while (highlights.length) {
    const highlightsItem = highlights.pop()
    if (Array.isArray(highlightsItem)) {
      highlightItems.push(...highlightsItem)
    } else {
      break
    }
  }
  const uniqHighlights = new Map<string, SingleHighlightInfo>()
  highlightItems.forEach((highlightItem) =>
    uniqHighlights.set(highlightItem.id, highlightItem),
  )

  return Array.from(uniqHighlights.values())
}

/**
 * Returns the number of digits after a comma.
 * A fixed version of the original implementation https://stackoverflow.com/a/27082406
 *
 * @export
 * @param {number} value - a float or integer
 * @return {number} - a number of digits after the comma.
 * e.g. for 0.001 it'll return 3.
 */
export function getNumberOfDigitsAfterComma(value: number): number {
  const stringRepresentation = value.toString()
  // verify if number 0.000005 is represented as "5e-6"
  if (stringRepresentation.indexOf('e-') > -1) {
    const [base, trail] = stringRepresentation.split('e-')
    const trailAsNumber = parseInt(trail, 10)
    const baseAsNumber = parseFloat(base)
    // e.g. 0.00000000999 => 9.99e-9, where base="9.99" and trail="9"
    const baseDigitsAfterComma = getNumberOfDigitsAfterComma(baseAsNumber)
    return trailAsNumber + baseDigitsAfterComma
  }
  // count decimals for number in representation like "0.123456"
  return stringRepresentation.split('.')[1]?.length ?? 0
}

/**
 * Rounds a numeric value to drop off an unnecessary real part of it.
 * The value will a have the same amount of digits after a comma as the
 * target number.
 *
 * @export
 * @param {number} value - a numeric value that will be rounded to have the same number
 * of digits of its real part as the "target".
 * @param {number} target - a numeric value which defines a number of digits after a comma.
 * @return {number} - rounded "value".
 */
export function roundToSamePrecision(value: number, target: number): number {
  const maxErrorDigitsAfterComma: number = getNumberOfDigitsAfterComma(target)
  if (!maxErrorDigitsAfterComma) {
    // if the 'maxError' is integer
    return Math.round(value)
  }
  const currentValueDigitsAfterComma: number = getNumberOfDigitsAfterComma(
    value,
  )
  if (currentValueDigitsAfterComma <= maxErrorDigitsAfterComma) {
    return value
  }
  return parseFloat(
    value.toFixed(
      Math.min(maxErrorDigitsAfterComma, 10), // to fixed throws an exception if the value is too big
    ),
  )
}

/**
 * Checks if x equals to y.
 *
 * @export
 * @param {number} x
 * @param {number} y
 * @param {number} [maxError=0]
 * @return {boolean} - checks if x equals to y or its value in the range of y +/- "maxError".
 */
export function equalTo(x: number, y: number, maxError = 0): boolean {
  const areEqual = x === y
  const areEqualWithError =
    areEqual || maxError
      ? // Check if  exceed the possible threshold.
        // If not to round the number the operation of subtraction will give a fancy
        // results in some cases. E.g 1 - 0.9998 = 0.00019999999999997797.
        // Thus the result of the function will be skewed by the error of subtraction.
        roundToSamePrecision(Math.abs(x - y), maxError) <= maxError
      : false
  return areEqualWithError
}

/**
 * Checks if x is greater or equal to y.
 *
 * @export
 * @param {number} x
 * @param {number} y
 * @param {number} [maxError=0] - the max allowed difference between two values.
 * @return {boolean} - If the difference between x and y not exceed the "maxError" limitation the result will be true.
 */
export function greaterOrEqualTo(x: number, y: number, maxError = 0): boolean {
  const diff = x - y
  return (
    // x >= y
    diff >= 0 ||
    // difference equal to zero with the allowed error taken into account
    equalTo(diff, 0, maxError)
  )
}

/**
 * Check x less or equal to y.
 *
 * @export
 * @param {number} x
 * @param {number} y
 * @param {number} [maxError=0] - an acceptable difference
 * @return {boolean} - returns true if x equals to y with regard to the error or if its value is greater.
 */
export function lessOrEqualTo(x: number, y: number, maxError = 0): boolean {
  return greaterOrEqualTo(y, x, maxError)
}

/**
 * Checks if two rects have an intersection.
 *
 * @export
 * @param {Rect} firstRect
 * @param {Rect} secondRect
 * @param {number} [0] - if it is defined, then all comparisons should be made with the allowance
 * of this value as a possible maximum error in the value of a coordinate.
 * @return {boolean} - true if they overlap
 */
export function checkIfTwoRectanglesOverlap(
  firstRect: Rect,
  secondRect: Rect,
  maxError = 0,
): boolean {
  const greaterOrEqualWithError = (x: number, y: number): boolean =>
    greaterOrEqualTo(x, y, maxError)
  const lessOrEqualWithError = (x: number, y: number): boolean =>
    lessOrEqualTo(x, y, maxError)
  const {
    y: secondRectTopLeftCornerYCoordinate,
    x: secondRectTopLeftCornerXCoordinate,
    width: secondRectWidth,
    height: secondRectHeight,
  } = secondRect
  const bottomRightSecondRectCoordinateOrNull =
    secondRectWidth && secondRectHeight
      ? {
          x: secondRectTopLeftCornerXCoordinate + secondRectWidth,
          y: secondRectTopLeftCornerYCoordinate + secondRectHeight,
        }
      : null
  const isSecondRectTopRightCornerOnTheSameRowsWithHighlight =
    greaterOrEqualWithError(secondRectTopLeftCornerYCoordinate, firstRect.y) &&
    lessOrEqualWithError(
      secondRectTopLeftCornerYCoordinate,
      firstRect.y + firstRect.height,
    )
  const isSecondRectTopLeftCornerOnTheSamePageWithHighlight =
    greaterOrEqualWithError(secondRectTopLeftCornerXCoordinate, firstRect.x) &&
    lessOrEqualWithError(
      secondRectTopLeftCornerXCoordinate,
      firstRect.x + firstRect.width,
    )
  const isSecondRectTopLeftCornerBelongsToHighlightRect =
    isSecondRectTopLeftCornerOnTheSamePageWithHighlight &&
    isSecondRectTopRightCornerOnTheSameRowsWithHighlight

  if (isSecondRectTopLeftCornerBelongsToHighlightRect) {
    return true
  }

  if (bottomRightSecondRectCoordinateOrNull) {
    const isSecondRectBottomRightCornerOnTheSameRowsWithHighlight =
      lessOrEqualWithError(
        firstRect.y,
        bottomRightSecondRectCoordinateOrNull.y,
      ) &&
      greaterOrEqualWithError(
        firstRect.y + firstRect.height,
        bottomRightSecondRectCoordinateOrNull.y,
      )
    const isSecondRectBottomRightCornerOnTheSamePageWithHighlight =
      greaterOrEqualWithError(
        bottomRightSecondRectCoordinateOrNull.x,
        firstRect.x,
      ) &&
      lessOrEqualWithError(
        bottomRightSecondRectCoordinateOrNull.x,
        firstRect.x + firstRect.width,
      )
    const isSecondRectBottomRightCornerBelongsToHighlightRect =
      isSecondRectBottomRightCornerOnTheSameRowsWithHighlight &&
      isSecondRectBottomRightCornerOnTheSamePageWithHighlight

    if (isSecondRectBottomRightCornerBelongsToHighlightRect) {
      return true
    }

    const isSecondRectTopLeftCornerAboveFirstRectTopLeftCorner = greaterOrEqualWithError(
      firstRect.y,
      secondRectTopLeftCornerYCoordinate,
    )
    const isSecondRectBottomRightCornerAboveFirstRectBottomRightCorner = greaterOrEqualWithError(
      bottomRightSecondRectCoordinateOrNull.y,
      firstRect.y + firstRect.height,
    )
    const isSecondRectTopLeftCornerBeforeFirstRectTopLeftCorner = lessOrEqualWithError(
      secondRectTopLeftCornerXCoordinate,
      firstRect.x,
    )
    const isSecondRectBottomRightCornerAfterFirstRectBottomRightCorner = greaterOrEqualWithError(
      bottomRightSecondRectCoordinateOrNull.x,
      firstRect.x + firstRect.width,
    )
    const isSecondRectEncompassesFirstRect: boolean =
      isSecondRectTopLeftCornerAboveFirstRectTopLeftCorner &&
      isSecondRectBottomRightCornerAboveFirstRectBottomRightCorner &&
      isSecondRectTopLeftCornerBeforeFirstRectTopLeftCorner &&
      isSecondRectBottomRightCornerAfterFirstRectBottomRightCorner

    return isSecondRectEncompassesFirstRect
  }
  return false
}
