import {
  Callback,
  CallSource,
  EventListenerService,
} from '@flowpub/glue-shared'

import { SelectionDirectionKey } from './types'
import { isRangeContainedWithinOtherRange } from './utils'
import { PageWordMap, WordSelection } from './page-word-map'
import { CurrentSelection } from './current-selection'

export const SelectFirstWordOnPage = 'SELECT_FIRST_WORD_ON_PAGE'
export const SelectNextWordInDirection = 'SELECT_NEXT_WORD_IN_DIRECTION'
export const ExpandSelectionInDirection = 'EXPAND_SELECTION_IN_DIRECTION'
export const ExitAssistiveSelectionMode = 'EXIT_ASSISTIVE_SELECTION_MODE'

interface WordRangeLocation {
  range: Range | null
  location: [number, number] | null
}

export class AssistiveSelectionHandlingService extends EventListenerService {
  public isAssistiveSelectionModeEnabled = false
  private pageWordMap: PageWordMap
  private curSelection: CurrentSelection

  constructor(source: CallSource) {
    super(source)

    source.bind(SelectFirstWordOnPage, this.selectFirstWordOnPage)
    source.bind(SelectNextWordInDirection, this.selectNextWordInDirection)
    source.bind(ExpandSelectionInDirection, this.expandSelectionInDirection)
    source.bind(ExitAssistiveSelectionMode, this.exitAssistiveSelectionMode)
  }

  /**
   * Sets up the word map and selects the first word
   *
   * @param _callback
   * @param pageStartCfi
   * @param pageEndCfi
   */
  private async selectFirstWordOnPage(
    _callback: Callback,
    pageStartCfi: string,
    pageEndCfi: string,
  ): Promise<void> {
    this.isAssistiveSelectionModeEnabled = true

    try {
      this.pageWordMap = new PageWordMap(pageStartCfi, pageEndCfi)
    } catch (e) {
      console.error(e)
      return
    }

    this.curSelection = new CurrentSelection()

    // Select first word on current page
    const curWordLineIndex = this.curSelection.getCurrentWordLineIndex()
    const curWordColumnIndex = this.curSelection.getCurrentWordColumnIndex()
    let firstWordOnPage: WordSelection | undefined

    try {
      firstWordOnPage = this.pageWordMap.getWordInLineByIndex(
        curWordLineIndex,
        curWordColumnIndex,
      )
    } catch (e) {
      console.error(e)
      return
    }

    if (!firstWordOnPage) {
      return
    }

    const firstWordRangeOnPage = firstWordOnPage.range.cloneRange()

    try {
      this.curSelection.updateCurrentSelection(firstWordRangeOnPage)
    } catch (e) {
      console.error(e)
    }
  }

  /**
   * Selects next word in given direction direction
   * Updates curWord  and curSelection to reflect this
   *
   * @param _callback
   * @param eventKey
   */
  private async selectNextWordInDirection(
    _callback: Callback,
    eventKey: SelectionDirectionKey,
  ): Promise<void> {
    if (!this.pageWordMap) {
      return
    }

    const nextWordRangeLocation = this.findNextWordRangeInMap(eventKey)

    if (!nextWordRangeLocation) {
      return
    }

    const {
      range: nextWordRange,
      location: nextWordLocation,
    } = nextWordRangeLocation

    if (!nextWordRange || !nextWordLocation) {
      return
    }

    // Update the cur word location with the found word
    this.curSelection.updateCurrentWord(nextWordLocation)

    try {
      this.curSelection.updateCurrentSelection(nextWordRange)
    } catch (e) {
      console.error(e)
    }
  }

  /**
   * Updates curSelection in given direction
   * This can be a shrink or expand, depending of whether the next word
   * in direction is already selected (shrink) or not (expand)
   *
   * @param _callback
   * @param eventKey
   */
  private async expandSelectionInDirection(
    _callback: Callback,
    eventKey: SelectionDirectionKey,
  ): Promise<void> {
    if (!this.pageWordMap || !this.curSelection) {
      return
    }

    const nextWordRangeLocation = this.findNextWordRangeInMap(eventKey)

    if (!nextWordRangeLocation) {
      return
    }

    const {
      range: nextWordRange,
      location: nextWordLocation,
    } = nextWordRangeLocation

    if (!nextWordRange || !nextWordLocation) {
      return
    }

    // Update the cur word location with the found word and update cur selection
    try {
      this.expandOrShrinkCurrentSelection(eventKey, nextWordRange)
    } catch (e) {
      console.error(e)
    }

    this.curSelection.updateCurrentWord(nextWordLocation)
  }

  private async exitAssistiveSelectionMode(): Promise<void> {
    this.curSelection.resetCurrentSelectionState()
    this.isAssistiveSelectionModeEnabled = false
  }

  /**
   * Finds next word range in given direction in the word map
   *
   * @param eventKey
   */
  private findNextWordRangeInMap(
    eventKey: SelectionDirectionKey,
  ): WordRangeLocation | null {
    let nextWordRangeLocation: WordRangeLocation | null

    if (this.isRightOrLeftKey(eventKey)) {
      nextWordRangeLocation = this.findNextWordRangeLeftOrRight(eventKey)
    } else if (this.isDownOrUpKey(eventKey)) {
      nextWordRangeLocation = this.findNextWordRangeUpOrDown(eventKey)
    } else {
      return null
    }

    return nextWordRangeLocation
  }

  /**
   * Finds next word going left or right
   *
   * @param eventKey
   */
  private findNextWordRangeLeftOrRight(
    eventKey: SelectionDirectionKey,
  ): WordRangeLocation | null {
    let nextWordRangeLocation: WordRangeLocation

    // If we go right, increase the index, otherwise decrease
    const nextIndexOffset = this.isRightKey(eventKey) ? 1 : -1

    const curWordColumnIndex = this.curSelection.getCurrentWordColumnIndex()
    const nextWordColumnIndex = curWordColumnIndex + nextIndexOffset
    const nextWordLineIndex = this.curSelection.getCurrentWordLineIndex()
    let nextWordInLine: WordSelection | undefined

    try {
      nextWordInLine = this.pageWordMap.getWordInLineByIndex(
        nextWordLineIndex,
        nextWordColumnIndex,
      )
    } catch (e) {
      console.error(e)
      return null
    }

    // Scan on the current line
    if (nextWordInLine) {
      // Update next word range and current word
      nextWordRangeLocation = {
        range: nextWordInLine.range,
        location: [nextWordLineIndex, nextWordColumnIndex],
      }
    } else {
      // Scan below or above for next line
      const nextLineWordLocation = this.findNextWordRangeOnNextLine(
        nextWordLineIndex,
        nextIndexOffset,
        eventKey,
      )

      if (!nextLineWordLocation) {
        return null
      }

      // Update next word range and current word
      nextWordRangeLocation = nextLineWordLocation
    }

    return nextWordRangeLocation
  }

  /**
   * When we select words using left and right keys, we can reach the end
   * of the current line. We want then to move the selection to the next/previous
   * line on subsequent left/right keys
   */
  private findNextWordRangeOnNextLine(
    lineIndex: number,
    nextLineIndexOffset: number,
    eventKey: SelectionDirectionKey,
  ): WordRangeLocation | null {
    const nextWordLineIndex = lineIndex + nextLineIndexOffset
    let nextLine: WordSelection[] | undefined
    try {
      nextLine = this.pageWordMap.getLineByIndex(nextWordLineIndex)
    } catch (e) {
      console.error(e)
    }

    if (!nextLine) {
      return null
    }

    const nextWordColumnIndex = this.isRightKey(eventKey)
      ? 0
      : nextLine.length - 1

    return {
      range: nextLine[nextWordColumnIndex].range,
      location: [nextWordLineIndex, nextWordColumnIndex],
    }
  }

  /**
   * Finds next word going up or down
   *
   * @param eventKey
   */
  private findNextWordRangeUpOrDown(
    eventKey: SelectionDirectionKey,
  ): WordRangeLocation | null {
    // If we go down, increase the index, otherwise decrease
    const nextIndexOffset = this.isDownKey(eventKey) ? 1 : -1

    // Scan below or above for next line
    const nextWordLineIndex =
      this.curSelection.getCurrentWordLineIndex() + nextIndexOffset
    let nextLine: WordSelection[] | undefined
    try {
      nextLine = this.pageWordMap.getLineByIndex(nextWordLineIndex)
    } catch (e) {
      console.error(e)
    }

    if (!nextLine) {
      return null
    }

    let closestWordOnLine: [WordSelection, number]

    try {
      closestWordOnLine = this.getClosestWordOnLine(nextLine)
    } catch (e) {
      console.error(e)
      return null
    }

    const [nextWord, nextWordColumnIndex] = closestWordOnLine

    return {
      range: nextWord.range,
      location: [nextWordLineIndex, nextWordColumnIndex],
    }
  }

  /**
   * Expands or shrinks current selection in a given direction
   *
   * @param eventKey
   * @param nextWordRange
   */
  private expandOrShrinkCurrentSelection(
    eventKey: SelectionDirectionKey,
    nextWordRange: Range,
  ): void {
    const curSelectionRange = this.curSelection.getCurrentSelectionRangeCopy()

    if (!curSelectionRange) {
      throw new Error(
        'Could not expand or shrink the selection - current selection is null',
      )
    }

    let modifiedSelectionRange: Range

    // If the next word is already in the range, we need to shrink current selection
    if (isRangeContainedWithinOtherRange(nextWordRange, curSelectionRange)) {
      modifiedSelectionRange = this.shrinkSelection(
        eventKey,
        nextWordRange,
        curSelectionRange,
      )
    } else {
      modifiedSelectionRange = this.expandSelection(
        eventKey,
        nextWordRange,
        curSelectionRange,
      )
    }

    try {
      this.curSelection.updateCurrentSelection(modifiedSelectionRange)
    } catch (e) {
      console.error(e)
    }
  }

  /**
   * Shrinks provided selection and returns it
   *
   * @param eventKey
   * @param nextWordRange
   * @param curSelectionRange
   */
  private shrinkSelection(
    eventKey: SelectionDirectionKey,
    nextWordRange: Range,
    curSelectionRange: Range,
  ): Range {
    if (this.isRightOrDownKey(eventKey)) {
      // Shrink from start
      curSelectionRange.setStart(
        nextWordRange.startContainer,
        nextWordRange.startOffset,
      )
    } else if (this.isLeftOrUpKey(eventKey)) {
      // Shrink from end
      curSelectionRange.setEnd(
        nextWordRange.endContainer,
        nextWordRange.endOffset,
      )
    }

    return curSelectionRange
  }

  /**
   * Expands provided selection and returns it
   *
   * @param eventKey
   * @param nextWordRange
   * @param curSelectionRange
   */
  private expandSelection(
    eventKey: SelectionDirectionKey,
    nextWordRange: Range,
    curSelectionRange: Range,
  ): Range {
    if (this.isRightOrDownKey(eventKey)) {
      curSelectionRange.setEnd(
        nextWordRange.endContainer,
        nextWordRange.endOffset,
      )
    } else if (this.isLeftOrUpKey(eventKey)) {
      curSelectionRange.setStart(
        nextWordRange.startContainer,
        nextWordRange.startOffset,
      )
    }

    return curSelectionRange
  }

  /**
   * For the current word, finds closest word on the line above or below
   * Metric: Minimal distance of 2 distances (from each edge of the word rect
   * to the current word's center)
   */
  private getClosestWordOnLine(
    nextLine: WordSelection[],
  ): [WordSelection, number] {
    const curWordLineIndex = this.curSelection.getCurrentWordLineIndex()
    const curWordColumnIndex = this.curSelection.getCurrentWordColumnIndex()
    const curWord = this.pageWordMap.getWordInLineByIndex(
      curWordLineIndex,
      curWordColumnIndex,
    )

    if (!curWord) {
      throw new Error(
        'Could not calculate next word, because current word is undefined',
      )
    }

    const curWordRect = curWord.rect
    const curWordLeft = curWordRect.left
    const curWordRight = curWordRect.left + curWordRect.width

    const curWordCenter = Math.round((curWordLeft + curWordRight) / 2)

    // Take the first word on the line above/below
    let closestWord = nextLine[0]
    let closestWordIndex = 0
    let closestWordDistance = this.getMinimalDistanceToCurWordCenter(
      closestWord,
      curWordCenter,
    )

    for (let i = closestWordIndex + 1; i < nextLine.length; i++) {
      const nextWord = nextLine[i]
      const nextWordDistance = this.getMinimalDistanceToCurWordCenter(
        nextWord,
        curWordCenter,
      )

      const isNextWordCloser = nextWordDistance < closestWordDistance

      if (isNextWordCloser) {
        closestWord = nextWord
        closestWordIndex = i
        closestWordDistance = nextWordDistance
      } else {
        break
      }
    }

    return [closestWord, closestWordIndex]
  }

  private getMinimalDistanceToCurWordCenter(
    word: WordSelection,
    curWordCenter: number,
  ): number {
    const wordLeft = word.rect.left
    const wordRight = word.rect.left + word.rect.width

    return Math.min(
      Math.abs(wordLeft - curWordCenter),
      Math.abs(wordRight - curWordCenter),
    )
  }

  private isRightOrDownKey(eventKey: SelectionDirectionKey): boolean {
    return this.isRightKey(eventKey) || this.isDownKey(eventKey)
  }

  private isLeftOrUpKey(eventKey: SelectionDirectionKey): boolean {
    return this.isLeftKey(eventKey) || this.isUpKey(eventKey)
  }

  private isRightOrLeftKey(eventKey: SelectionDirectionKey): boolean {
    return this.isRightKey(eventKey) || this.isLeftKey(eventKey)
  }

  private isDownOrUpKey(eventKey: SelectionDirectionKey): boolean {
    return this.isDownKey(eventKey) || this.isUpKey(eventKey)
  }

  private isLeftKey(eventKey: SelectionDirectionKey): boolean {
    return eventKey === SelectionDirectionKey.ArrowLeft
  }

  private isRightKey(eventKey: SelectionDirectionKey): boolean {
    return eventKey === SelectionDirectionKey.ArrowRight
  }

  private isDownKey(eventKey: SelectionDirectionKey): boolean {
    return eventKey === SelectionDirectionKey.ArrowDown
  }

  private isUpKey(eventKey: SelectionDirectionKey): boolean {
    return eventKey === SelectionDirectionKey.ArrowUp
  }
}
