import * as EPUBcfi from '@evidentpoint/readium-cfi-js'

import {
  classBlacklist,
  elementBlacklist,
  idBlacklist,
} from '../default-blacklist'

/**
 * Checks if a given char is a separator
 * Separator means White Spaces and Line Terminators
 * For more info see the character class [\s]
 * https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide/Regular_Expressions/Character_Classes
 *
 * @param char
 */
export function isCharSeparator(char: string): boolean {
  const separatorRegExp = /\s/
  return separatorRegExp.test(char)
}

/**
 * Finds index of next non-separator character from a given index in a string
 * Separators are matched with [\s] class
 * Return null if non-separator char was not found
 *
 * @param text
 * @param startIndex
 */
export function findNextNonSeparatorCharIndexOrNull(
  text: string,
  startIndex: number,
): number | null {
  let i = startIndex
  let currentChar = text[i]

  while (isCharSeparator(currentChar)) {
    if (i === text.length - 1) {
      return null // last char is separator, nothing to search for
    }

    i += 1
    currentChar = text[i]
  }

  return i
}

/**
 * Checks if a valid text node (of text type,
 * not empty, does not contain spaces only)
 *
 * @param node
 */
export function isTrimmedTextNodeNotEmpty(node: Node): boolean {
  if (node.nodeType === Node.TEXT_NODE) {
    const text = node.nodeValue

    if (text === null) {
      return false
    }

    return !!text.trim().length
  }

  return false
}

/**
 * Get text children of an element
 *
 * @param root
 * @param nodeFilter - a filter object implementing the NodeFilter interface
 */
export function getTextChildrenOfNode(
  root: Node,
  nodeFilter?: NodeFilter,
): Node[] {
  const textNodes: Node[] = []
  const nodeFilterOrDefault = nodeFilter || {
    acceptNode: (node: Node): number => {
      return isTrimmedTextNodeNotEmpty(node)
        ? NodeFilter.FILTER_ACCEPT
        : NodeFilter.FILTER_REJECT
    },
  }

  const nodeIterator = document.createNodeIterator(
    root,
    NodeFilter.SHOW_TEXT,
    nodeFilterOrDefault,
  )

  let node = nodeIterator.nextNode()
  let prevNode = null

  while (node) {
    if (prevNode === node) {
      break
    }

    textNodes.push(node)

    prevNode = node
    node = nodeIterator.nextNode()
  }

  return textNodes
}

/**
 * Check if range is contained within another range
 *
 * @param sourceRange - range to check against
 * @param range - range to check
 */
export function isRangeContainedWithinOtherRange(
  range: Range,
  sourceRange: Range,
): boolean {
  // Check if sourceRange overlaps range from the left
  const leftOverlapResult = sourceRange.compareBoundaryPoints(
    Range.START_TO_START,
    range,
  )
  // Check if sourceRange overlaps range from the right
  const rightOverlapResult = sourceRange.compareBoundaryPoints(
    Range.END_TO_END,
    range,
  )

  const rangeIsContainedOnLeftEdge =
    leftOverlapResult === -1 || leftOverlapResult === 0
  const rangeIsContainedOnRightEdge =
    rightOverlapResult === 1 || rightOverlapResult === 0

  return rangeIsContainedOnLeftEdge && rangeIsContainedOnRightEdge
}

/**
 * Get text terminus info or element by partial CFI
 *
 * @param partialCFI
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export function getTextTerminusOrElement(partialCFI: string): any {
  if (EPUBcfi.Interpreter.hasTextTerminus(`epubcfi(/99!${partialCFI})`)) {
    let textTerminusResult
    try {
      textTerminusResult = EPUBcfi.Interpreter.getTextTerminusInfo(
        `epubcfi(/99!${partialCFI})`,
        document,
        classBlacklist,
        idBlacklist,
        elementBlacklist,
      )
      return textTerminusResult
    } catch (ex) {
      // EPUBcfi.Interpreter can throw a SyntaxError
      console.error(ex)
    }
  } else {
    let el
    try {
      el = EPUBcfi.Interpreter.getTargetElement(
        `epubcfi(/99!${partialCFI})`,
        document,
        classBlacklist,
        idBlacklist,
        elementBlacklist,
      )
      return el[0]
    } catch (ex) {
      // EPUBcfi.Interpreter can throw a SyntaxError
      console.error(ex)
    }
  }

  return null
}
