export interface Rect {
  x: number
  y: number
  width: number
  height: number
}

// PageLabelLocationType replicated in flowpub/core/packages/navigator/src/page-label-handling.ts
export enum PageLabelLocationType {
  Anchor,
  CFI,
  Offset,
  None,
}

export type PageLabelInfo = {
  type: PageLabelLocationType
  location: string | number
  label: string
  spineItemIndex: number
}

export type PageLabelInfoWithPosition = PageLabelInfo & {
  position: Rect
  timestampMs: number
}

export enum Comparison {
  Forward = -1,
  Identical = 0,
  Backward = 1,
}
