import {
  EventListenerService,
  CallSource,
  Callback,
} from '@flowpub/glue-shared'
import * as EPUBcfi from '@evidentpoint/readium-cfi-js'

import { PageLabelLocationType } from './types'
import type { Rect, PageLabelInfo, PageLabelInfoWithPosition } from './types'
import {
  elementBlacklist,
  idBlacklist,
  classBlacklist,
} from './default-blacklist'

type PageLabelViewTargetNode = HTMLElement | Text

interface PageLabelViewWithElementAndOffset {
  pageLabelView: PageLabelView
  targetNode: PageLabelViewTargetNode
  // timestamp when the info was updated
  targetOffset?: number
}

type MapPageLabelViewWithElementAndOffset = Map<
  PageLabelViewTargetNode,
  PageLabelViewWithElementAndOffset[]
>

export const PageLabelAddMessage = 'PAGE_LABEL_ADD'
export const PageLabelViewportUdateMessage = 'PAGE_LABEL_VIEWPORT_UPDATE'
export const PageLabelAriaLabelUpdateMessage = 'PAGE_LABEL_ARIA_LABEL_UPDATE'

const IframeWindowResizeTimeoutMs = 500

const IframeWindowResizeMaxAttemptsCount = 3

export class PageLabelHandlingService extends EventListenerService {
  private pageLabelViews: PageLabelView[] = []

  constructor(source: CallSource) {
    super(source)

    source.bind(
      PageLabelAddMessage,
      this.handleWithPageLabelsPositionsUpdateResult(this.addPageLabels),
    )
    source.bind(
      PageLabelViewportUdateMessage,
      this.getPageLabelsPositionsUpdated.bind(this),
    )
    source.bind(
      PageLabelAriaLabelUpdateMessage,
      this.handleWithPageLabelsPositionsUpdateResult(this.ariaLabelUpdate),
    )
  }

  private handleWithPageLabelsPositionsUpdateResult(
    listener: (...args: any[]) => Promise<void>,
  ) {
    const boundListener = listener.bind(this)
    return async (...args: any[]): Promise<string> => {
      await boundListener(...args)
      const pageLabelsWithPositionsUpdated = await this.getPageLabelsPositionsUpdated()
      return pageLabelsWithPositionsUpdated
    }
  }

  private async getPageLabelsPositionsUpdated(): Promise<string> {
    const updatedPageLabelsPositions = await this.getUpdatedPageLabelsInfoWithPositionStringifiedOnNextRenderCycle()
    return updatedPageLabelsPositions
  }

  private async addPageLabels(
    _: Callback,
    pageLabelListJson: string,
    ariaLabel: string,
  ): Promise<void> {
    const pageLabels = JSON.parse(pageLabelListJson) as PageLabelInfo[]
    let deferredRendering = false
    const pageLabelsMap: MapPageLabelViewWithElementAndOffset = new Map()

    for (const pageLabel of pageLabels) {
      if (pageLabel.type === PageLabelLocationType.Anchor) {
        const element = document.getElementById(pageLabel.location as string)
        if (element) {
          const pageLabelView = new PageLabelView(pageLabel, ariaLabel)
          pageLabelView.setRefElement(element)
          pageLabelView.renderView()
          this.pageLabelViews.push(pageLabelView)
        }
      } else if (pageLabel.type === PageLabelLocationType.CFI) {
        // Avoid changing the DOM before we go through all page label CFIs
        // otherwise the CFI may reference incorrect nodes
        deferredRendering = true
        this.addPageLabelViewFromCfi(pageLabel, ariaLabel, pageLabelsMap)
      }
    }

    const orderedPageLabelsViewsWithOffsetsAndTargetNodes = this.getOrderedPageLabelsViewsForTheSameTextTargetNode(
      pageLabelsMap,
    )

    orderedPageLabelsViewsWithOffsetsAndTargetNodes.forEach(
      (
        pageLabelsViewsWithOffsetsAndTargetNode: PageLabelViewWithElementAndOffset,
      ) => {
        this.setUpPageLabelViewParamsByLabelDescriptionsWithUpdatedOffsets(
          pageLabelsViewsWithOffsetsAndTargetNode,
        )
        this.pageLabelViews.push(
          pageLabelsViewsWithOffsetsAndTargetNode.pageLabelView,
        )
      },
    )
    await new Promise((res) => {
      setTimeout(() => {
        // for cfi base page label, the rendering has to be in the next
        // run loop somehow, otherwise label's postion will be wrong
        if (deferredRendering) {
          this.renderPageLabelViews()
        }
        res(undefined)
      }, 0)
    })
    await this._recalculatePageLabelsPositions(this.pageLabelViews)
  }

  protected getOrderedPageLabelsViewsForTheSameTextTargetNode(
    mapPageLabelViewWithElementAndOffset: MapPageLabelViewWithElementAndOffset,
  ): PageLabelViewWithElementAndOffset[] {
    const pageLabelsDescriptionsList = Array.from(
      mapPageLabelViewWithElementAndOffset.values(),
    )
    const pageLabelsDescriptionsWithUpdatedOffsetsOrderedList: PageLabelViewWithElementAndOffset[] = []

    for (const pageLabelsDescriptionsForParentNode of pageLabelsDescriptionsList) {
      /*
       We have to render from the biggest offset to the lowest one.
       Because if we try to render unordered list of PageLabelViews a shared text node
       might be cut out by a previous label with a less offset, thus if the current
       page label has a larger offset, the 'refTextNode.splitText' will throw, because
       the refTextNode's had a less length than before it was splitted.
      */
      const orderedByOffset = pageLabelsDescriptionsForParentNode.sort(
        (
          pageLabelViewWithOffsetA: PageLabelViewWithElementAndOffset,
          pageLabelViewWithOffsetB: PageLabelViewWithElementAndOffset,
        ) =>
          Number(pageLabelViewWithOffsetB.targetOffset) -
          Number(pageLabelViewWithOffsetA.targetOffset),
      )
      orderedByOffset.forEach(
        (pageLabelViewWithOffset: PageLabelViewWithElementAndOffset): void => {
          pageLabelsDescriptionsWithUpdatedOffsetsOrderedList.push(
            pageLabelViewWithOffset,
          )
        },
      )
    }
    return pageLabelsDescriptionsWithUpdatedOffsetsOrderedList
  }

  protected setUpPageLabelViewParamsByLabelDescriptionsWithUpdatedOffsets(
    pageLabelDescriptionsWithUpdatedOffsetAndTargetNode: PageLabelViewWithElementAndOffset,
  ) {
    const {
      pageLabelView,
      targetNode,
      targetOffset,
    } = pageLabelDescriptionsWithUpdatedOffsetAndTargetNode
    if (targetNode.nodeType === Node.TEXT_NODE) {
      pageLabelView.setRefNode(targetNode as Text, Number(targetOffset))
    } else {
      pageLabelView.setRefElement(targetNode as HTMLElement)
    }
  }

  private addPageLabelViewFromCfi(
    pageLabel: PageLabelInfo,
    ariaLabel: string,
    mapPageLabelViewWithElementAndOffset: MapPageLabelViewWithElementAndOffset,
  ): void {
    let targetNode: HTMLElement | undefined = undefined
    let targetOffset: number | undefined = undefined
    const pageLabelView = new PageLabelView(pageLabel, ariaLabel)

    if (EPUBcfi.Interpreter.hasTextTerminus(pageLabel.location)) {
      const textTerminusResult = EPUBcfi.Interpreter.getTextTerminusInfo(
        pageLabel.location as string,
        document,
        classBlacklist,
        idBlacklist,
        elementBlacklist,
      )
      targetNode = textTerminusResult.textNode
      targetOffset = textTerminusResult.textOffset
    } else {
      const $element = EPUBcfi.Interpreter.getTargetElement(
        pageLabel.location,
        document,
        classBlacklist,
        idBlacklist,
        elementBlacklist,
      )
      if (!$element || $element.length === 0) {
        console.error(`Can't find element for CFI: ${pageLabel.location}`)
        return
      }
      const element = $element[0]
      if (element.nodeType === Node.TEXT_NODE) {
        targetNode = element
        targetOffset = 0
      } else {
        targetNode = element
      }
    }

    if (targetNode) {
      const mapPageLabelViewWithElementAndOffsetArray =
        mapPageLabelViewWithElementAndOffset.get(targetNode) ?? []

      mapPageLabelViewWithElementAndOffsetArray.push({
        pageLabelView,
        targetNode,
        targetOffset,
      })
      mapPageLabelViewWithElementAndOffset.set(
        targetNode,
        mapPageLabelViewWithElementAndOffsetArray,
      )
    }
  }

  private getTimestampForPageLabel(): number {
    return Date.now()
  }

  private renderPageLabelViews(): void {
    for (const view of this.pageLabelViews) {
      view.renderView()
    }
  }

  private async ariaLabelUpdate(_: Callback, ariaLabel: string): Promise<void> {
    for (const view of this.pageLabelViews) {
      view.setAriaLabel(ariaLabel)
    }
  }

  private getUpdatedPageLabelsInfoWithPosition(): PageLabelInfoWithPosition[] {
    const updatedPositions = []
    const timestampMs: number = this.getTimestampForPageLabel()
    for (const view of this.pageLabelViews) {
      view.calculateAndUpdatePageLabelPosition()
      updatedPositions.push({
        ...view.labelInfoWithPosition,
        timestampMs,
      })
    }
    return updatedPositions
  }

  private getUpdatedPageLabelsInfoWithPositionStringified(): string {
    const updatedPageLabelsInfoWithPosition = this.getUpdatedPageLabelsInfoWithPosition()
    return JSON.stringify(updatedPageLabelsInfoWithPosition)
  }

  private whetherLabelHasWrongPosition(pageLabel: PageLabelView): boolean {
    return window.innerHeight <= pageLabel.labelInfoWithPosition.position.y
  }

  private async _waitForIframeResizeOrTimeout(): Promise<void> {
    /**
     * After user's resized the window or just open a new page of a book we send into the iframe a command to recalculate positions
     * of all page labels or add new ones. But it take some time for the iframe before it will get a stable width, so we need to wait
     * until the 'resize' event before we can get accurate positions of page labels.
     */
    let timer: ReturnType<typeof setTimeout>
    let windowResizeListener: EventListener
    const resizePromise = new Promise((res) => {
      windowResizeListener = () => {
        clearTimeout(timer)
        res(undefined)
      }
      window.addEventListener('resize', res, { once: true })
    })
    const timeoutPromise = new Promise((_res, rej) => {
      timer = setTimeout(() => {
        window.removeEventListener('resize', windowResizeListener)
        rej()
      }, IframeWindowResizeTimeoutMs)
    })
    await Promise.race([resizePromise, timeoutPromise])
  }

  private async _recalculatePageLabelsPositions(
    pageLabelViews: PageLabelView[],
    recalculationAttempt = 0,
  ): Promise<void> {
    const pageLabelViewsWithWrongPositions: PageLabelView[] = []
    for (const pageLabelView of pageLabelViews) {
      pageLabelView.calculateAndUpdatePageLabelPosition()
      if (this.whetherLabelHasWrongPosition(pageLabelView)) {
        pageLabelViewsWithWrongPositions.push(pageLabelView)
      }
    }
    if (pageLabelViewsWithWrongPositions.length) {
      if (recalculationAttempt > IframeWindowResizeMaxAttemptsCount) {
        throw new Error('Calculation of page labels positions has failed')
      }
      await this._waitForIframeResizeOrTimeout()
      await this._recalculatePageLabelsPositions(
        pageLabelViewsWithWrongPositions,
        recalculationAttempt + 1,
      )
    }
  }

  private getUpdatedPageLabelsInfoWithPositionStringifiedOnNextRenderCycle(): Promise<
    string
  > {
    return new Promise((res) => {
      // TODO - it helped to calculate right page labels positions on iOS somehow, but we need to verify it
      setTimeout(() => {
        res(this.getUpdatedPageLabelsInfoWithPositionStringified())
      })
    })
  }
}

class PageLabelView {
  public get labelInfoWithPosition(): Omit<
    PageLabelInfoWithPosition,
    'timestampMs'
  > {
    return {
      ...this.labelInfo,
      position: this.containerElementPosition,
    }
  }

  private refElement: Element
  private refTextNode: Text
  private refTextOffset: number

  private containerElement?: HTMLElement
  private label: string
  private ariaLabel: string
  private labelInfo: PageLabelInfo

  private containerElementPosition: Rect = {
    x: 0,
    y: 0,
    width: 0,
    height: 0,
  }

  public constructor(labelInfo: PageLabelInfo, ariaLabel: string) {
    this.label = labelInfo.label
    this.ariaLabel = ariaLabel
    this.labelInfo = labelInfo
  }

  public setRefElement(ele: HTMLElement): void {
    this.refElement = ele
  }

  public setRefNode(node: Text, offset: number): void {
    this.refTextNode = node
    this.refTextOffset = offset
  }

  public renderView(): void {
    const containerEle = document.createElement('span')
    containerEle.style.display = 'inline-block'
    containerEle.style.userSelect = 'none'
    // screen readers don't read elements with zero size
    containerEle.style.height = '1px'
    containerEle.style.width = '1px'
    containerEle.classList.add('flowpub-page-label-container')
    // Stop VoiceOver saying the word "group"
    // https://blog.chrisworfolk.com/how-to-stop-voiceover-saying-the-word-group
    containerEle.setAttribute('role', 'text')
    this.containerElement = containerEle
    this.setAriaLabel(this.ariaLabel)
    if (this.refElement) {
      this.refElement.parentElement?.insertBefore(containerEle, this.refElement)
    } else if (this.refTextNode) {
      let insertRef = this.refTextNode
      if (this.refTextOffset > 0) {
        insertRef = this.refTextNode.splitText(this.refTextOffset)
      }
      this.refTextNode.parentElement?.insertBefore(
        this.containerElement,
        insertRef,
      )
    }
  }

  public setAriaLabel(ariaLabel: string): void {
    this.ariaLabel = ariaLabel
    this.containerElement?.setAttribute(
      'aria-label',
      `${this.ariaLabel} ${this.label}`.trim(),
    )
  }

  public calculateAndUpdatePageLabelPosition(): void {
    const pageLabelElementRefRectOrNull = this.getRefRect()
    if (!pageLabelElementRefRectOrNull) {
      return
    }

    this.updateContainerPositionByContainerDOMRect(
      pageLabelElementRefRectOrNull,
      {
        top: 0,
        left: 0,
      },
    )
  }

  private getRefRect(): DOMRect | null {
    let refRect = null

    if (this.refTextNode) {
      refRect = this.calculatePageLabelPosition(this.refTextNode)
    }
    if (refRect) {
      return refRect
    }

    if (this.refElement) {
      refRect = this.refElement.getClientRects()[0]
      if (refRect) {
        return refRect
      }
    }

    if (!this.containerElement) {
      return refRect
    }

    // We could fail to get rects from element in the case that
    // it is a hidden element, so we will try to figure out
    // its coordinates from its sibling.
    // If prev text node exist, we will use DOM range, otherwise
    // prev element will be used
    const prevNode = this.containerElement.previousSibling
    if (prevNode && prevNode.nodeType === Node.TEXT_NODE) {
      refRect = this.calculateTextPosition(prevNode as Text, true)
    }
    if (refRect) {
      return refRect
    }

    const prevElement = this.containerElement.previousElementSibling
    if (prevElement) {
      const rects = prevElement.getClientRects()
      refRect = rects[rects.length - 1]
    }
    return refRect
  }

  private calculatePositionOfTextNode(node: Text, offset: number): DOMRect {
    const textPosRange = document.createRange()
    textPosRange.setStart(node, offset)
    textPosRange.setEnd(node, offset)
    return textPosRange.getClientRects()[0]
  }

  private calculatePositionOfRange(node: Text, offset: number): DOMRect {
    let remainingOffset = offset
    let rect: DOMRect | null = null
    const parentElement = node.parentElement
    let lastChildNode: Node = node
    parentElement?.childNodes.forEach((childNode) => {
      if (rect) {
        return
      }
      lastChildNode = childNode
      if (childNode instanceof Text && !(childNode instanceof HTMLElement)) {
        if (childNode.length > remainingOffset) {
          rect = this.calculatePositionOfTextNode(childNode, remainingOffset)
          return
        }
        remainingOffset -= childNode.length
      }
    })
    if (!rect) {
      const textPosRange = document.createRange()
      textPosRange.selectNodeContents(lastChildNode)
      return textPosRange.getBoundingClientRect()
    }
    return rect
  }

  private calculatePageLabelPosition(node: Text): DOMRect {
    const offset = this.refTextOffset
    return this.calculatePositionOfRange(node, offset)
  }

  private calculateTextPosition(node: Text, fromEnd: boolean): DOMRect {
    const offset = fromEnd ? node.length : 0
    return this.calculatePositionOfRange(node, offset)
  }

  private updateContainerPositionByContainerDOMRect(
    pageLabelDOMRect: DOMRect,
    adjustmentValues: {
      top: number
      left: number
    },
  ): void {
    const { x, y, height, width } = pageLabelDOMRect
    this.containerElementPosition = {
      x: x + adjustmentValues.left,
      y: y + adjustmentValues.top,
      height: height,
      width: width,
    }
  }
}
