import {
  Callback,
  CallSource,
  EventListenerService,
} from '@flowpub/glue-shared'

export const WheelMessageAddListener = 'ADD_WHEEL_LISTENER'
export const WheelMessageRemoveListener = 'REMOVE_WHEEL_LISTENER'

// https://developer.apple.com/documentation/webkitjs/gestureevent
interface GestureEvent extends UIEvent {
  readonly altKey: boolean
  readonly clientX: number
  readonly clientY: number
  readonly ctrlKey: boolean
  readonly metaKey: boolean
  readonly rotation: number
  readonly scale: number
  readonly screenX: number
  readonly screenY: number
  readonly shiftKey: boolean
}

export class WheelHandlingService extends EventListenerService {
  private lastScale = 1

  constructor(source: CallSource) {
    super(source)
    source.bind(WheelMessageAddListener, this.addWheelListener)
    source.bind(WheelMessageRemoveListener, this.removeEventListener)
  }

  private async addWheelListener(callback: Callback): Promise<number> {
    const gestureEndListener: EventListener = (_event: Event) => {
      this.lastScale = 1
    }
    this.registerListenerForTargets(
      '@document',
      'gestureend',
      gestureEndListener,
    )

    const gestureListener: EventListener = (event: Event) => {
      const { clientY, clientX, scale } = event as GestureEvent

      // gesture event reports scale as fraction where gestureStart defines scale = 1
      // deltaY is difference between this scale and scale at last event
      const deltaY = (1 - scale / this.lastScale) * 100

      callback(false, clientX, clientY, true, deltaY)

      this.lastScale = scale
    }

    // gesture change activated on macOS safari and ios browsers
    // only use gesture change event for macOS
    if (!('ontouchend' in document)) {
      this.registerListenerForTargets(
        '@document',
        'gesturechange',
        gestureListener,
      )
    }

    const listener: EventListener = (event: Event) => {
      const wheelEvent = event as WheelEvent

      callback(
        true,
        wheelEvent.clientX,
        wheelEvent.clientY,
        wheelEvent.ctrlKey,
        wheelEvent.deltaY,
      )
    }

    return this.registerListenerForTargets('@document', 'wheel', listener)
  }

  private async removeEventListener(
    _callback: Callback,
    listenerID: number,
  ): Promise<void> {
    this.removeEventListeners(listenerID)
  }
}
