import { FocusableElement, tabbable } from 'tabbable'
import {
  EventListenerService,
  CallSource,
  Callback,
} from '@flowpub/glue-shared'

import { getRectsFromDomRects, calculateRectsMinMax } from './utils'

export const AddFocusableElementEndListenerMessage =
  'ADD_FOCUSABLE_ELEMENT_END_LISTENER'
export const RemoveFocusableElementEndListenerMessage =
  'REMOVE_FOCUSABLE_ELEMENT_END_LISTENER'
export const EnableTabFocusMessage = 'ENBABLE_TABFOCUS'
export const FocusMessage = 'FOCUS'
export const TabFocusVisibleRangeUpdateMessage = 'TABFOCUS_VISIBLE_RANGE_UPDATE'

export class TabFocusHandlingService extends EventListenerService {
  private isEnabled = false

  private focusableElements: FocusableElement[] | null = null
  private visibleFocusableElements: FocusableElement[] = []

  private currFocusedIndex = -1

  private elementEndCallback: Callback | null = null

  private visibleRange = [-1, -1]

  constructor(source: CallSource) {
    super(source)

    source.bind(
      AddFocusableElementEndListenerMessage,
      this.addFocusableElementEndListener,
    )

    source.bind(FocusMessage, this.focus)
    source.bind(TabFocusVisibleRangeUpdateMessage, this.visibleRangeUpdate)
    source.bind(EnableTabFocusMessage, this.enableTabFocus)

    this.onKeydown = this.onKeydown.bind(this)
  }

  private tabNext(): void {
    this.currFocusedIndex++
    if (this.currFocusedIndex >= this.visibleFocusableElements.length) {
      this.currFocusedIndex = -1
      if (this.elementEndCallback) {
        this.elementEndCallback()
      }
      return
    }

    this.visibleFocusableElements[this.currFocusedIndex].focus()
  }

  private async addFocusableElementEndListener(
    callback: Callback,
  ): Promise<number> {
    this.elementEndCallback = callback
    return 0
  }

  private async enableTabFocus(
    _callback: Callback,
    enabled: boolean,
  ): Promise<void> {
    if (enabled && !this.isEnabled) {
      document.addEventListener('keydown', this.onKeydown)
    } else if (!enabled && this.isEnabled) {
      document.removeEventListener('keydown', this.onKeydown)
    }
    this.isEnabled = enabled
  }

  private async focus(): Promise<boolean> {
    if (this.visibleFocusableElements.length === 0) {
      // nothing to focus on
      return false
    }

    this.currFocusedIndex = 0
    this.visibleFocusableElements[this.currFocusedIndex].focus()
    return true
  }

  private async visibleRangeUpdate(
    _: Callback,
    startOffset: number,
    endOffset: number,
  ): Promise<void> {
    this.visibleRange[0] = startOffset
    this.visibleRange[1] = endOffset

    this.ensureFocusableElementsCollected()

    if (!this.focusableElements || this.focusableElements.length === 0) {
      return
    }

    this.visibleFocusableElements = []
    for (const ele of this.focusableElements) {
      const rects = getRectsFromDomRects(ele.getClientRects())
      const [minX, maxX] = calculateRectsMinMax(rects)
      if (minX > this.visibleRange[1] || maxX < this.visibleRange[0]) {
        continue
      }
      this.visibleFocusableElements.push(ele)
    }
  }

  private ensureFocusableElementsCollected(): void {
    if (this.focusableElements === null && document.body) {
      this.focusableElements = tabbable(document.body)
    }
  }

  private onKeydown(kbEvent: KeyboardEvent): void {
    if (kbEvent.key === 'Tab') {
      kbEvent.preventDefault()

      this.tabNext()
    }
  }
}
