/**
 * Manages current state of assistive selection: currently active word
 * and selection
 */
export class CurrentSelection {
  private curWord = [0, 0]
  private curSelection: Range | null

  public getCurrentWordLineIndex(): number {
    return this.curWord[0]
  }

  public getCurrentWordColumnIndex(): number {
    return this.curWord[1]
  }

  public getCurrentSelectionRangeCopy(): Range | null {
    if (!this.curSelection) {
      throw Error(
        'Could not get current selection range, because current selection is null',
      )
    }

    return this.curSelection.cloneRange()
  }

  public updateCurrentSelection(selection: Range) {
    this.curSelection = selection
    this.updateDocumentSelection()
  }

  public updateCurrentWord(curWord: [number, number]) {
    this.curWord = curWord
  }

  public resetCurrentSelectionState() {
    this.curWord = [0, 0]
    this.curSelection = null
  }

  private updateDocumentSelection() {
    if (!this.curSelection) {
      throw Error(
        'Could not add selection to document, because there current selection is null',
      )
    }

    const selection = document.getSelection()
    if (!selection) {
      throw Error('Could not get selection from the document')
    }

    selection.removeAllRanges()
    selection.addRange(this.curSelection.cloneRange())
  }
}
