import {
  EventListenerService,
  CallSource,
  Callback,
} from '@flowpub/glue-shared'
import * as EPUBcfi from '@evidentpoint/readium-cfi-js'
import { degausser } from 'degausser'

import {
  elementBlacklist,
  idBlacklist,
  classBlacklist,
} from './default-blacklist'
import {
  HighlightHandlingService,
  SelectedHighlightInfo,
} from './highlight-handling'
import { Rect } from './types'
import {
  collectNodesWithinRange,
  getHrefFromElement,
  mergeHighlightListsToUniqHighlights,
} from './utils'
import { AssistiveSelectionHandlingService } from './assistive-selection/assistive-selection-handling'

export const SelectionChangingMessageAddListener =
  'ADD_SELECTION_CHANGING_LISTENER'
export const SelectionChangeMessageAddListener = 'ADD_SELECTION_CHANGE_LISTENER'
export const SelectionChangeMessageRemoveListener =
  'REMOVE_SELECTION_CHANGE_LISTENER'
export const ClearSelection = 'CLEAR_SELECTION'
export const GetSelectionData = 'GET_SELECTION_DATA'

interface SelectionData {
  content: string
  start: {
    cfi: string
    offset: number
  }
  end: {
    cfi: string
    offset: number
  }
  rects: Rect[]
  highlights: SelectedHighlightInfo
  highlightOverlappingByPosition: string[]
  href: string | null
}

function isTextNode(node: Node): node is Text {
  return node.nodeType === Node.TEXT_NODE
}

function getNodeMaxLength(node: Node): number {
  return isTextNode(node) ? node.wholeText.length : node.childNodes.length
}

export class SelectionChangeHandlingService extends EventListenerService {
  private isSelecting = false
  private userAgent = ''

  private highlightService: HighlightHandlingService | null = null
  private assistiveSelectionService: AssistiveSelectionHandlingService | null = null

  constructor(source: CallSource) {
    super(source)

    this.detectUserAgent()

    source.bind(
      SelectionChangeMessageAddListener,
      this.addSelectionChangeListener,
    )
    source.bind(
      SelectionChangingMessageAddListener,
      this.addSelectionChangingListener,
    )
    source.bind(SelectionChangeMessageRemoveListener, this.removeEventListener)
    source.bind(ClearSelection, this.clearSelection)
    source.bind(GetSelectionData, this.getSelectionData)
  }

  public setHighlightService(hs: HighlightHandlingService): void {
    this.highlightService = hs
  }

  public setAssistiveSelectionService(
    assistiveSelectionService: AssistiveSelectionHandlingService,
  ): void {
    this.assistiveSelectionService = assistiveSelectionService
  }

  private detectUserAgent(): void {
    const userAgent = navigator.userAgent

    if (userAgent.indexOf('Android') > -1) {
      this.userAgent = 'Android'
    }
  }

  private async addSelectionChangeListener(
    callback: Callback,
  ): Promise<number> {
    if (this.userAgent === 'Android') {
      const contextListener: EventListener = (e: Event) => {
        e.preventDefault()

        const targetNode = e.target as Element

        if (targetNode && targetNode.tagName.toLowerCase() === 'a') {
          const anchorRange = this.getRangeForAnchor(targetNode)

          if (anchorRange) {
            callback(this.getData(anchorRange))
            return
          }

          callback(null)
          return
        }

        callback(this.getData())
      }

      const nullSelectionListener: EventListener = () => {
        if (this.isSelectionNull()) {
          callback(null)
        }
      }

      this.registerListenerForTargets(
        '@document',
        'selectionchange',
        nullSelectionListener,
      )

      return this.registerListenerForTargets(
        '@document',
        'contextmenu',
        contextListener,
      )
    } else {
      const selectionListener: EventListener = (e: Event) => {
        e.preventDefault()

        if (this.assistiveSelectionService?.isAssistiveSelectionModeEnabled) {
          return callback(this.getData())
        }

        const isNull = this.isSelectionNull()

        if (isNull) {
          callback(null)
          this.isSelecting = false
        } else {
          this.isSelecting = true
        }
      }

      const touchListener: EventListener = () => {
        if (this.isSelecting) {
          this.isSelecting = false
          callback(this.getData())
        }
      }

      this.registerListenerForTargets('@document', 'pointerup', touchListener)

      return this.registerListenerForTargets(
        '@document',
        'selectionchange',
        selectionListener,
      )
    }
  }

  private async addSelectionChangingListener(
    callback: Callback,
  ): Promise<number> {
    return this.registerListenerForTargets(
      '@document',
      'selectionchange',
      () => {
        callback(this.getData())
      },
    )
  }

  private async getSelectionData(): Promise<SelectionData | null> {
    return this.getData()
  }

  private async removeEventListener(
    _callback: Callback,
    listenerID: number,
  ): Promise<void> {
    this.removeEventListeners(listenerID)
  }

  private isSelectionNull(): boolean {
    const selection = document.getSelection()
    if (!selection || selection.rangeCount < 1 || selection.isCollapsed) {
      // I don't think selection range is ever 0
      return true
    }

    return false
  }

  private getData(anchorRange?: Range): SelectionData | null {
    const isNull = this.isSelectionNull()
    if (!anchorRange && isNull) {
      return null
    }

    // Alright, there's a bug with WKWebview in that the Selection
    //  and its Range has different content. This happens because of
    //  CSS applied on certain text sections, which is evidently picked up
    //  by Selection but not in its Range. For an example, see
    //  the beginning of any chapter in Metamorphosis. The effect is
    //  only present in the same paragraph as the CSS applied text.

    // Selection already checked for null
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    const selection = document.getSelection()!

    if (anchorRange) {
      selection.setBaseAndExtent(
        anchorRange.startContainer,
        0,
        anchorRange.endContainer,
        anchorRange.endOffset,
      )
    }

    // Only Gecko allows multiple ranges, we can ignore for now
    // Selection already checked for null
    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    let range = selection.getRangeAt(0)!

    const href = this.getAnchorFromRange(range)

    const selectionString = selection.toString()
    let rangeString = range.toString()

    // The only way we can figure out if there's an error in the range is
    //  to compare the strings
    if (
      selectionString.toLocaleLowerCase() !== rangeString.toLocaleLowerCase() &&
      selectionString.replace(/\s+/g, '') !== rangeString.replace(/\s+/g, '')
    ) {
      range = range.cloneRange()

      // The user cannot actually select the Drop Cap in Metamorphosis.
      //  In this case, the Webview will assume the user has selected the
      //  Drop Cap if the user selects all the way to the beginning of the
      //  text immediately following the Drop Cap. However, this causes
      //  the range reported to be short by a number of characters equal
      //  to the Drop Cap length.
      if (selectionString.length !== rangeString.length) {
        const difference = selectionString.length - rangeString.length
        range.setEnd(
          range.endContainer,
          Math.max(range.endOffset + difference, 0),
        )

        rangeString = range.toString()
      }

      const selectionStringFitlered = selectionString.replace(/\s+/g, '')

      // Selection and Range strings will actually return different results when
      //  they cross Paragraphs. Specifically, the Selection string will return
      //  Char 10 (LF), whereas Range string will only return Char 32 (space)
      while (selectionStringFitlered !== rangeString.replace(/\s+/g, '')) {
        // If the user does not actually select up to the Drop Cap, then
        //  the contents of the strings are shifted by a number of characters
        //  equal to the Drop Cap length. To compensate, we progressively test
        //  the string until we get the correct section

        const { startContainer } = range
        const startOffsetNextValue = range.startOffset + 1
        if (getNodeMaxLength(startContainer) < startOffsetNextValue) {
          break
        }
        range.setStart(startContainer, startOffsetNextValue)

        const { endContainer } = range
        const endOffsetNextValue = range.endOffset + 1
        if (getNodeMaxLength(endContainer) < endOffsetNextValue) {
          break
        }
        range.setEnd(endContainer, endOffsetNextValue)

        rangeString = range.toString()
      }
    }

    const allRects = range.getClientRects()
    const rectList: Rect[] = []
    for (let i = 0; i < allRects.length; ++i) {
      const rect = allRects.item(i)
      if (!rect) {
        continue
      }
      rectList.push(this.getSingleRect(rect))
    }

    const startRange = range.cloneRange()
    const endRange = range.cloneRange()

    startRange.collapse(true)
    const startCfi = this.generateCfi(startRange)
    startRange.setStartBefore(
      startRange.startContainer?.ownerDocument?.documentElement as Node,
    )
    const startOffset = degausser(startRange.cloneContents(), {
      classBlacklist,
      idBlacklist,
      elementBlacklist,
    }).length

    endRange.collapse(false)
    const endCfi = this.generateCfi(endRange)
    endRange.setStartBefore(
      endRange.startContainer?.ownerDocument?.documentElement as Node,
    )
    const endOffset = degausser(endRange.cloneContents(), {
      classBlacklist,
      idBlacklist,
      elementBlacklist,
    }).length

    const firstRect = rectList[0]
    const selectedHighlights: SelectedHighlightInfo = {
      touchPoint: firstRect,
      highlights: [],
    }
    let highlightOverlappingByPosition: string[] = []

    if (this.highlightService) {
      // each rectangle should be considered, since a selection might have a fancy shape
      // which can not be described with only one rectangle
      for (const rect of rectList) {
        // Round coordinates because the browser may return
        // a value of coordinate with too many digits after
        // a comma. That may lead to an incorrect detection
        // of intersection with highlight rects.
        // E.g. if rect.x = 399.99 and highlight.x = 400.
        // Add up 1 pixel to the top vertical coordinate and
        // subtract 1 pixel from the bottom coordinate. The reason
        // of that is the hight probability of having the issue
        // with comparing coordinates which are too precise and
        // have a lot of digits after a comma.
        // Another issue issue is that a selection made by the user
        // and the highlighted text differ in top/bottom coordinates
        // at around 1 pixel, even though the selected/highlighted text
        // is the same and located on the same line. So we add 1px to the
        // vertical coordinates only as a compensation.

        const yTop = Math.floor(rect.y) + 1
        const xLeft = Math.floor(rect.x)
        const yBottom = Math.floor(rect.y + rect.height) - 1
        const xRight = Math.floor(rect.x + rect.width)
        const selectedHighlightsWithLeftCorner = this.highlightService.getSelectedHighlights(
          xLeft,
          yTop,
          { x: xRight, y: yBottom },
        )

        selectedHighlights.highlights = mergeHighlightListsToUniqHighlights(
          selectedHighlights.highlights,
          selectedHighlightsWithLeftCorner.highlights,
        )

        highlightOverlappingByPosition = this.highlightService.getOverlappingHighlightIds(
          document.getSelection()?.getRangeAt(0),
        )
      }
    }

    return {
      content: selectionString,
      start: {
        cfi: startCfi,
        offset: startOffset,
      },
      end: {
        cfi: endCfi,
        offset: endOffset,
      },
      rects: rectList,
      highlights: selectedHighlights,
      highlightOverlappingByPosition: highlightOverlappingByPosition,
      href,
    }
  }

  // Copied and adapted from CFI-Nav-Logic
  private generateCfi(range: Range): string {
    if (!range.collapsed) {
      console.error('Not collapsed range')
      return ''
    }
    if (isTextNode(range.startContainer)) {
      return EPUBcfi.Generator.generateCharacterOffsetCFIComponent(
        range.startContainer,
        range.startOffset,
        classBlacklist,
        idBlacklist,
        elementBlacklist,
      )
    } else {
      let cfi = EPUBcfi.Generator.generateElementCFIComponent(
        range.startContainer as Element,
      )

      if (cfi[0] === '!') {
        cfi = cfi.substring(1)
      }

      return cfi
    }
  }

  private getSingleRect(domRect: DOMRect): Rect {
    return {
      x: domRect.left,
      y: domRect.top,
      width: domRect.width,
      height: domRect.height,
    }
  }

  private async clearSelection(): Promise<void> {
    const selection = document.getSelection()
    if (!selection || selection.rangeCount < 1 || selection.isCollapsed) {
      return
    }

    selection.removeAllRanges()
  }

  private getRangeForAnchor(targetAnchor: Node): Range | null {
    const treeWalker = document.createTreeWalker(
      targetAnchor,
      NodeFilter.SHOW_TEXT,
    )

    let textNode = null

    do {
      const node = treeWalker.currentNode
      if (isTextNode(node)) {
        textNode = node
      }
    } while (treeWalker.nextNode())

    if (!textNode) {
      console.error('No text to highlight')
      return null
    }

    const anchorRange = new Range()
    anchorRange.setStart(textNode, 0)
    anchorRange.setEnd(textNode, textNode.wholeText.length)

    return anchorRange
  }

  private getAnchorFromRange(range: Range): string | null {
    const startNode = range.startContainer
    let shouldSkipFirstNode = false
    if (startNode.nodeType === 3) {
      const textNode = startNode as Text
      if (textNode.length <= range.startOffset) {
        shouldSkipFirstNode = true
      }
    }

    if (!shouldSkipFirstNode) {
      const nodes = this.getAncestors(startNode)
      for (const n of nodes) {
        const href = this.getAnchorFromNode(n)
        if (href) {
          return href
        }
      }
    }

    const nodes = collectNodesWithinRange(range)
    if (nodes.length === 0) {
      return null
    }

    for (const n of nodes) {
      const href = this.getAnchorFromNode(n)
      if (href) {
        return href
      }
    }

    return null
  }

  private getAnchorFromNode(node: Node): string | null {
    if (node.nodeType === 1) {
      const ele = node as Element
      if (ele.tagName === 'a') {
        return getHrefFromElement(ele as HTMLElement)
      }
    }
    return null
  }

  private getAncestors(node: Node): Element[] {
    let currEle: Element | null = null
    const elements = []
    if (node.nodeType === 1) {
      currEle = node as Element
    } else {
      currEle = node.parentElement
    }

    while (currEle !== null) {
      elements.push(currEle)
      currEle = currEle.parentElement
    }

    return elements
  }
}
