import {
  Callback,
  CallSource,
  EventListenerService,
  TouchTracker,
} from '@flowpub/glue-shared'

import { getHrefFromElement } from './utils'

export const LinkHandlingMessageAddListener = 'ADD_LINK_LISTENER'
export const LinkHandlingMessageRemoveListener = 'REMOVE_LINK_LISTENER'

interface MouseEventWithLocations extends MouseEvent {
  [key: string]: unknown
}

export class LinkHandlingService extends EventListenerService {
  constructor(source: CallSource) {
    super(source)
    source.bind(LinkHandlingMessageAddListener, this.addLinkListener)
    source.bind(LinkHandlingMessageRemoveListener, this.removeEventListener)
  }

  private async addLinkListener(callback: Callback): Promise<number> {
    const touchTracker = new TouchTracker(10, 500)

    let isKeyboardEvent = false

    const listener: EventListener = (event) => {
      let canTrigger = false

      if (isKeyboardEvent) {
        canTrigger = true
      } else {
        touchTracker.onPointerUp(event as MouseEvent)

        const tapDone = touchTracker.isDone()
        const wasShort = !touchTracker.pressedLong()
        const didntDrag = !touchTracker.movedLong()

        canTrigger = tapDone && wasShort && didntDrag
      }

      if (canTrigger) {
        event.preventDefault()
        event.stopPropagation()
        event.stopImmediatePropagation()

        const href = this.extractHref(event)
        callback(href)
      }
    }

    // Prevent browser opening the link
    // Also note that we use pointer events instead of the click event
    // for triggering links. On mobile devices, tapping on the screen
    // triggers pointer events instead of a click event.
    // If we were to trigger links with click events, but still listen
    // for pointer events, there could be a conflict where tapping
    // on a link also triggers pointer event listeners.
    // For this reason, we are using pointer events across the board.
    // The logic below only makes an exception for 'click' events
    // triggered by the keyboard.
    this.registerListenerForTargets('a', 'click', (event) => {
      event.preventDefault()
      event.stopPropagation()
      event.stopImmediatePropagation()

      const locationProps: string[] = [
        'clientX',
        'clientY',
        'screenX',
        'screenY',
        'pageX',
        'pageY',
      ]

      if (
        locationProps.some(
          (prop: string) => (event as MouseEventWithLocations)[prop] !== 0,
        )
      ) {
        return
      }

      isKeyboardEvent = true
      listener(event)

      isKeyboardEvent = false
    })

    this.registerListenerForTargets('a', 'pointerdown', (event) => {
      touchTracker.onPointerDown(event as MouseEvent)
    })

    this.registerListenerForTargets('a', 'pointermove', (event) => {
      touchTracker.onPointerMove(event as MouseEvent)

      event.preventDefault()
      event.stopPropagation()
      event.stopImmediatePropagation()
    })

    this.registerListenerForTargets('a', 'dragstart', (event) => {
      event.preventDefault()
      event.stopPropagation()
      event.stopImmediatePropagation()
    })

    // Add listener to the pointerup event so we won't trigger
    // tap on page callback
    return this.registerListenerForTargets('a', 'pointerup', listener)
  }

  private async removeEventListener(
    _callback: Callback,
    listenerID: number,
  ): Promise<void> {
    this.removeEventListeners(listenerID)
  }

  private extractHref(e: Event): string {
    const href = getHrefFromElement(e.currentTarget as HTMLElement)
    return href === null ? '' : href
  }
}
