import {
  findNextNonSeparatorCharIndexOrNull,
  getTextChildrenOfNode,
  getTextTerminusOrElement,
  isCharSeparator,
  isTrimmedTextNodeNotEmpty,
} from './utils'

export interface WordSelection {
  range: Range
  rect: DOMRect
}

/**
 * Constructs word matrix as a two-dimensional array and allows
 * to fetch words by indices
 */
export class PageWordMap {
  private readonly pageWordMap: WordSelection[][]

  constructor(pageStartCfi: string, pageEndCfi: string) {
    // Convert CFIs to Range
    const pageRange = this.getRangeFromCfi(pageStartCfi, pageEndCfi)

    if (!pageRange) {
      throw new Error('Could not construct page range from the given CFIs')
    }

    // Get text nodes for words in the page range
    const pageWordMap = this.getTextNodesRangesOnPage(pageRange)

    if (!pageWordMap) {
      throw new Error(
        'Could not construct page word matrix from the given page range',
      )
    }

    this.pageWordMap = pageWordMap
  }

  public getLineByIndex(index: number): WordSelection[] | undefined {
    if (!this.pageWordMap) {
      throw new Error('Page word map is not set')
    }

    return this.pageWordMap[index]
  }

  public getWordInLineByIndex(
    lineIndex: number,
    columnIndex: number,
  ): WordSelection | undefined {
    if (!this.pageWordMap) {
      throw new Error('Page word map is not set')
    }

    return this.pageWordMap[lineIndex][columnIndex]
  }

  /**
   * Build a page range from start/end CFIs
   *
   * @param pageStartCfi
   * @param pageEndCfi
   */
  private getRangeFromCfi(
    pageStartCfi: string,
    pageEndCfi: string,
  ): Range | null {
    const startPosition = getTextTerminusOrElement(pageStartCfi)
    const endPosition = getTextTerminusOrElement(pageEndCfi)
    if (startPosition === null || endPosition === null) {
      return null
    }

    const range = document.createRange()

    this.setRangeBoundary(range, 'start', startPosition)
    this.setRangeBoundary(range, 'end', endPosition)

    return range
  }

  /**
   * Set range start or end boundary
   *
   * @param range
   * @param boundary
   * @param position
   */
  private setRangeBoundary(
    range: Range,
    boundary: string,
    position: any,
  ): void {
    const rangeBoundaryPosition: [Node, number] = position.textNode
      ? [position.textNode, position.textOffset]
      : [position, 0]

    if (boundary === 'start') {
      range.setStart(...rangeBoundaryPosition)
    } else if (boundary === 'end') {
      range.setEnd(...rangeBoundaryPosition)
    }
  }

  /**
   * Get all text nodes(one for each word) for current page range
   * Returns a 2D array of words objects (rect + range for each word)
   */
  private getTextNodesRangesOnPage(pageRange: Range): WordSelection[][] | null {
    if (!pageRange) {
      return null
    }

    // Get text node ranges on the page
    const textNodeRanges = this.getTextNodeRanges(pageRange)

    if (!textNodeRanges) {
      return null
    }

    // Split text node ranges into word ranges
    const wordRanges = this.splitTextNodeRangesIntoWordRanges(textNodeRanges)

    if (!wordRanges) {
      return null
    }

    // Enhance word ranges with rects
    const wordRangesWithRects = this.getWordRangesWithRects(wordRanges)
    return this.getWordRangesWithRectsGroupedVertically(wordRangesWithRects)
  }

  private getTextNodeRanges(pageRange: Range): Range[] | null {
    const firstRange = pageRange.cloneRange()

    if (!firstRange.startContainer || !firstRange.startContainer.textContent) {
      return null
    }

    const textNodeRanges: Range[] = []
    let shouldSearch = true

    // Nothing to search for if we only have one element on page
    if (firstRange.startContainer === firstRange.endContainer) {
      shouldSearch = false
    } else {
      firstRange.setEnd(
        firstRange.startContainer,
        firstRange.startContainer.textContent.length,
      )
    }

    textNodeRanges.push(firstRange)

    let nextTextNode = shouldSearch
      ? this.findNextTextNodeOnCurPage(
          true,
          firstRange.startContainer,
          pageRange,
        )
      : null

    // Calc text node ranges
    while (nextTextNode && pageRange.endContainer !== nextTextNode) {
      const range = document.createRange()
      range.selectNodeContents(nextTextNode)
      textNodeRanges.push(range)

      nextTextNode = this.findNextTextNodeOnCurPage(
        true,
        nextTextNode,
        pageRange,
      )
    }

    // Calc last text node range
    if (pageRange.endContainer.nodeType === Node.TEXT_NODE && shouldSearch) {
      const lastRange = pageRange.cloneRange()
      lastRange.setStart(lastRange.endContainer, 0)
      textNodeRanges.push(lastRange)
    }

    return textNodeRanges
  }

  private splitTextNodeRangesIntoWordRanges(
    textNodeRanges: Range[],
  ): Range[] | null {
    const wordRanges: Range[] = []

    // Split text node ranges into word ranges
    for (const range of textNodeRanges) {
      const rangeText = range.startContainer.textContent

      if (!rangeText) {
        return null
      }

      // Skip any spaces in the beginning of the text
      let startIndex = findNextNonSeparatorCharIndexOrNull(
        rangeText,
        range.startOffset,
      )

      // Skip text node range because it has spaces only
      if (startIndex === null) {
        continue
      }

      let endIndex = startIndex + 1

      while (endIndex <= range.endOffset) {
        const charAtEndIndex = rangeText[endIndex]

        if (isCharSeparator(charAtEndIndex)) {
          const newRange = document.createRange()
          newRange.setStart(range.startContainer, startIndex)
          newRange.setEnd(range.endContainer, endIndex)
          wordRanges.push(newRange)

          startIndex = findNextNonSeparatorCharIndexOrNull(rangeText, endIndex)

          // Next non-space was not found, meaning there is no more words to search
          if (startIndex === null) {
            break
          }

          endIndex = startIndex
        }

        endIndex += 1
      }

      // No more words to search in current range
      if (startIndex === null) {
        continue
      }

      // Last word range
      const newRange = document.createRange()
      newRange.setStart(range.startContainer, startIndex)
      newRange.setEnd(range.endContainer, endIndex - 1)

      if (!newRange.collapsed) {
        wordRanges.push(newRange)
      }
    }

    return wordRanges
  }

  private getWordRangesWithRects(wordRanges: Range[]): WordSelection[] {
    return wordRanges.map((range) => ({
      range,
      rect: range.getBoundingClientRect(),
    }))
  }

  private getWordRangesWithRectsGroupedVertically(
    wordRangesWithRects: WordSelection[],
  ): WordSelection[][] {
    const groupedRangesWithRects: WordSelection[][] = []
    let currentTop = wordRangesWithRects[0].rect.top
    let lineRects: WordSelection[] = []

    for (const rangeWithRect of wordRangesWithRects) {
      if (rangeWithRect.rect.top === currentTop) {
        lineRects.push(rangeWithRect)
      } else {
        groupedRangesWithRects.push(lineRects)
        lineRects = [rangeWithRect]
        currentTop = rangeWithRect.rect.top
      }
    }

    // Push last line
    groupedRangesWithRects.push(lineRects)

    return groupedRangesWithRects
  }

  /**
   * Find closest text node (next or previous) on the page
   *
   * @param forward
   * @param curNode
   * @param pageRange
   */
  private findNextTextNodeOnCurPage(
    forward: boolean,
    curNode: any,
    pageRange: Range,
  ): Node | null {
    if (!pageRange) {
      return null
    }

    let nextTextNode: any = null

    let node = forward ? curNode.nextSibling : curNode.previousSibling

    while (node) {
      if (isTrimmedTextNodeNotEmpty(node)) {
        nextTextNode = node
        break
      } else {
        const isElement =
          node.nodeType === Node.ELEMENT_NODE &&
          (node as Element).childNodes.length > 0

        if (isElement) {
          const textNodes = getTextChildrenOfNode(node)

          if (textNodes.length) {
            nextTextNode = forward
              ? textNodes[0]
              : textNodes[textNodes.length - 1]
            break
          }
        }

        if (pageRange.endContainer === node) {
          return null
        }

        const curNodeRange = document.createRange()
        curNodeRange.selectNodeContents(node)

        // If node is not in current page range, bail out
        if (
          curNodeRange.compareBoundaryPoints(Range.END_TO_END, pageRange) === 1
        ) {
          return null
        }

        node = forward ? node.nextSibling : node.previousSibling
      }
    }

    if (!nextTextNode) {
      return this.findNextTextNodeOnCurPage(
        forward,
        curNode.parentElement,
        pageRange,
      )
    }

    return nextTextNode
  }
}
